import net.runelite.api.ChatMessageType;

/**
 * The sample lines the developer-mode command {@code ::hoverinfo demo} posts into the player's own chatbox, so the cards
 * can be hovered at once without waiting for a clan mate's drop. Plain data: each lot adds a list of its own here and
 * one line in {@link #lines()}.
 */
final class DemoLines
{
	/** One line to post: the chat type, the speaking player's name and the text. */
	static final class Line
	{
		/** The chat type the line is posted as. */
		final ChatMessageType type;
		/** The speaking player for a typed chat line; empty for a broadcast. */
		final String name;
		/** The line's text. */
		final String text;

		Line(ChatMessageType type, String name, String text)
		{
			this.type = type;
			this.name = name;
			this.text = text;
		}
	}

	/** The five item broadcasts: a drop, a stacked drop, a clue item, a collection log item and a drop that says where it came from. */
	static final List<Line> ITEMS = Collections.unmodifiableList(Arrays.asList(
		new Line(ChatMessageType.CLAN_MESSAGE, "", "Klar received a drop: Dragon claws (121,453,000 coins)."),
		new Line(ChatMessageType.FRIENDSCHATNOTIFICATION, "",
			"Iron Pete received a drop: 10 x Black knife (460 coins)."),
		new Line(ChatMessageType.CLAN_GUEST_MESSAGE, "", "Klar received a clue item: Ranger boots (25,296,193 coins)."),
		new Line(ChatMessageType.CLAN_GIM_MESSAGE, "",
			"Mossy Rock received a new collection log item: Abyssal whip (1/484)."),
		new Line(ChatMessageType.CLAN_MESSAGE, "",
			"N o r s received a drop: 45 x Runite ore (456,345 coins) from Duke Sucellus.")));

	/** Two of the player's own game lines: a valuable drop and a new collection log item. */
	static final List<Line> OWN = Collections.unmodifiableList(Arrays.asList(
		new Line(ChatMessageType.GAMEMESSAGE, "", "Valuable drop: Dragon claws (121,453,000 coins)"),
		new Line(ChatMessageType.GAMEMESSAGE, "", "New item added to your collection log: Abyssal whip")));

	/**
	 * Eight clan broadcasts that are not about an item: two quests, one in the game's string-variable form, a combat
	 * task, a pet, a level, XP, a diary and a best; and a ninth, the player's own game line for a level gained.
	 */
	static final List<Line> KINDS = Collections.unmodifiableList(Arrays.asList(
		new Line(ChatMessageType.CLAN_MESSAGE, "", "Klar has completed a quest: Dragon Slayer II"),
		new Line(ChatMessageType.CLAN_MESSAGE, "",
			"<str_quest_name_0=King's Ransom>Iron Pete has completed a quest: <str_quest_name_0>"),
		new Line(ChatMessageType.CLAN_MESSAGE, "",
			"CA_ID:279|Mossy Rock has completed a Master combat task: Perfect Zulrah (5 points)."),
		new Line(ChatMessageType.CLAN_MESSAGE, "",
			"Iron Pete has a funny feeling like he's being followed: Pet snakeling at 2,678 killcount."),
		new Line(ChatMessageType.CLAN_MESSAGE, "", "Klar has reached Defence level 70."),
		new Line(ChatMessageType.CLAN_MESSAGE, "", "Klar has reached 200,000,000 XP in Cooking."),
		new Line(ChatMessageType.CLAN_MESSAGE, "", "Mossy Rock has completed the Elite Ardougne diary."),
		new Line(ChatMessageType.CLAN_MESSAGE, "", "Iron Pete has achieved a new Vorkath personal best: 2:28"),
		new Line(ChatMessageType.GAMEMESSAGE, "",
			"Congratulations, you've just advanced your Sailing level. You are now level 47.")));

	private DemoLines()
	{
	}

	/** Every sample line, section by section, in the order they are posted. */
	static List<Line> lines()
	{
		final List<Line> all = new ArrayList<>(ITEMS);
		all.addAll(OWN);
		all.addAll(KINDS);
		return all;
	}
}

package com.clanhub;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ScheduledExecutorService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The drop rates of the Old School RuneScape Wiki, from the table the plugin bundles
 * ({@code /com/clanhub/drops.json}, built from the wiki's drop data and credited in its own header): for an item's name,
 * the sources it drops from, the most likely first. The table is read once, off the client thread, a second or two
 * after start-up; until then, and for ever if the file is missing or unreadable, every lookup answers an empty list and
 * the item card simply shows no Drop row. Parsing is pure and is the only part that needs the table's shape.
 *
 * <p>Choice: the load task runs once; a plugin restart runs it again.
 */
final class DropRates
{
	private static final Logger log = LoggerFactory.getLogger(DropRates.class);

	/** Where the bundled table lives on the classpath. */
	private static final String RESOURCE = "/com/clanhub/drops.json";

	/** One place an item drops from, with how often. */
	static final class DropSource
	{
		/** The source's name, such as "Abyssal demon" or "Chambers of Xeric". */
		final String from;
		/** The rate as the wiki writes it, such as "1/512", "1/171.6" or "Rare". */
		final String rate;
		/** The wiki page of the source, such as "Abyssal_demon". */
		final String wiki;

		DropSource(String from, String rate, String wiki)
		{
			this.from = from;
			this.rate = rate;
			this.wiki = wiki;
		}
	}

	/** A table read whole: the sources by the item's exact name, and by its name ignoring case. */
	private static final class Table
	{
		private final Map<String, List<DropSource>> exact = new HashMap<>();
		private final Map<String, List<DropSource>> ignoringCase = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
	}

	/** The table once loaded; null until the load has published it. */
	private volatile Table table;

	/** A table that has not loaded: every lookup answers nothing and {@link #loaded()} is false. */
	DropRates()
	{
	}

	private DropRates(Table table)
	{
		this.table = table;
	}

	/**
	 * Reads the table's shape: {@code {"items": {"<item name>": [{"from": "...", "rate": "...", "wiki": "..."}]}}}.
	 * A missing or empty {@code items} gives an empty table that counts as loaded.
	 *
	 * <p>Choice: a source with no {@code from} or no {@code rate} is skipped, an item left with no source is left out,
	 * and a missing {@code wiki} reads as an empty text; nothing in the file's shape that is merely odd stops the rest
	 * of the table being read.
	 *
	 * @throws com.google.gson.JsonParseException when the text is not JSON
	 */
	static DropRates parse(Reader json, Gson gson)
	{
		final Table read = new Table();
		final JsonObject root = gson.fromJson(json, JsonObject.class);
		if (root != null && root.has("items") && root.get("items").isJsonObject())
		{
			for (final Map.Entry<String, JsonElement> item : root.getAsJsonObject("items").entrySet())
			{
				final List<DropSource> sources = sourcesOf(item.getValue());
				if (!sources.isEmpty())
				{
					final List<DropSource> kept = Collections.unmodifiableList(sources);
					read.exact.put(item.getKey(), kept);
					read.ignoringCase.putIfAbsent(item.getKey(), kept);
				}
			}
		}
		return new DropRates(read);
	}

	/** The sources one item's array holds, the file's order kept. */
	private static List<DropSource> sourcesOf(JsonElement array)
	{
		final List<DropSource> sources = new ArrayList<>();
		if (!array.isJsonArray())
		{
			return sources;
		}
		for (final JsonElement entry : array.getAsJsonArray())
		{
			if (!entry.isJsonObject())
			{
				continue;
			}
			final JsonObject source = entry.getAsJsonObject();
			final String from = text(source, "from");
			final String rate = text(source, "rate");
			if (!from.isEmpty() && !rate.isEmpty())
			{
				sources.add(new DropSource(from, rate, text(source, "wiki")));
			}
		}
		return sources;
	}

	/** The text of a member, or an empty text when it is missing or is not a string. */
	private static String text(JsonObject object, String member)
	{
		final JsonElement value = object.get(member);
		return value != null && value.isJsonPrimitive() ? value.getAsString() : "";
	}

	/**
	 * The sources the item drops from, the most likely first: those of the exact name, else of the name ignoring case,
	 * else an empty list. Also an empty list while the table has not loaded.
	 */
	List<DropSource> lookup(String itemName)
	{
		final Table loaded = table;
		if (loaded == null || itemName == null)
		{
			return Collections.emptyList();
		}
		final List<DropSource> exact = loaded.exact.get(itemName);
		if (exact != null)
		{
			return exact;
		}
		final List<DropSource> similar = loaded.ignoringCase.get(itemName);
		return similar != null ? similar : Collections.<DropSource>emptyList();
	}

	/** Whether the table has been read and published. */
	boolean loaded()
	{
		return table != null;
	}

	/**
	 * Reads the bundled table on the executor and publishes it. A missing resource or a table that does not parse leaves
	 * this empty and logs one warning naming the cause; nothing is thrown out of the task.
	 *
	 * <p>Choice: after a failed load {@link #loaded()} stays false, since nothing was published.
	 */
	void loadInBackground(ScheduledExecutorService executor, Gson gson)
	{
		executor.execute(() -> load(gson));
	}

	/** The load task: one classpath read, one parse, one publish. */
	private void load(Gson gson)
	{
		try (InputStream in = DropRates.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("The drop rate table {} is not in the plugin; the cards show no drop rates", RESOURCE);
				return;
			}
			table = parse(new InputStreamReader(in, StandardCharsets.UTF_8), gson).table;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("The drop rate table {} could not be read ({}); the cards show no drop rates", RESOURCE, e.toString());
		}
	}
}

package com.clanhub;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;

/**
 * The how-to's "Examine" icon, drawn in code beside {@link GearGlyph}: a magnifying glass, a ring for the lens and a short
 * round-capped handle going down and to the right. The game has no sprite for it, and the picture is the same shape at any
 * size, every length being a fraction of the size.
 */
final class ExamineGlyph
{
	/** The smallest side drawn: below it the lens closes. */
	static final int MIN_SIZE = 7;

	private ExamineGlyph()
	{
	}

	/**
	 * A new square icon, transparent except for the lens and its handle.
	 *
	 * @param size   the icon's side in px; anything under {@value #MIN_SIZE} is raised to it
	 * @param colour the ink; null falls back to the sidebar's quiet grey, {@link ColorScheme#LIGHT_GRAY_COLOR}
	 */
	static ImageIcon icon(int size, Color colour)
	{
		final int s = Math.max(MIN_SIZE, size);
		final BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			g.setColor(colour == null ? ColorScheme.LIGHT_GRAY_COLOR : colour);
			// The lens: a ring whose centre line has this radius, in the upper left; the handle starts on the ring's
			// edge, on the diagonal, and ends short of the corner so that its round cap lands inside the icon.
			final double lensCentre = s * 0.40;
			final double lens = s * 0.27;
			final float lensWidth = (float) Math.max(1.5, s * 0.11);
			final float handleWidth = (float) Math.max(1.8, s * 0.15);
			final double edge = lens + lensWidth / 2.0;
			final double start = lensCentre + edge * Math.cos(Math.PI / 4.0);
			final double end = s - handleWidth / 2.0 - 1.0;
			g.setStroke(new BasicStroke(lensWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.draw(new Ellipse2D.Double(lensCentre - lens, lensCentre - lens, lens * 2.0, lens * 2.0));
			g.setStroke(new BasicStroke(handleWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.draw(new Line2D.Double(start, start, end, end));
		}
		finally
		{
			g.dispose();
		}
		return new ImageIcon(img);
	}
}

package com.clanhub;

import com.clanhub.ClanHubConfig.ExamineLine;
import java.util.Collections;
import java.util.List;
import java.util.function.BooleanSupplier;
import java.util.function.IntSupplier;
import java.util.function.Supplier;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.util.Text;

/**
 * The reader of the player's own examine lines: the text the game writes when the player examines an item or a monster, a
 * card for the thing examined, its name or its whole text the hover words. The text names nothing ("A pristine mole skin." is what an
 * immaculate mole skin says), so the line alone cannot give the card. RuneLite tells a plugin what the player clicked
 * Examine on, as its own Examine plugin learns what to price: the plugin passes each such click to {@link #clicked}, this
 * reader remembers the one thing last examined and the game tick it was clicked on, and the examine line that follows
 * within {@link #FRESH_TICKS} ticks gets that thing's card. An item gives the {@link ItemCards} card of its id (a noted
 * item or a placeholder gives the item itself); a monster gives the marked card of its name, with the wiki's own picture
 * and, for a boss the {@link CardTables} know, its facts. An object gives none.
 *
 * <p>Choice: the text names nothing, so with the "Examine line" setting at "Item name first" (the default) the plugin
 * writes the thing's name into the line before the readers see it, "Law rune: Used for teleport spells.", and {@link
 * #read} then covers the name alone, so the hover words are the name and the description stays plain beside it; at
 * "Description only" the line stays as the game wrote it and the whole text is the hover words. {@link #label} makes the
 * line as it should read, and remembers and forgets nothing, so {@link #read} still answers the click.
 *
 * <p>Choice: one click gives one card. The thing is forgotten once its line has been read, because RuneLite's Examine plugin
 * writes a price line of its own after the game's, and that line is not an examine line of the player's.
 *
 * <p>Choice: only the player's own examine lines are read, the {@code ITEM_EXAMINE} and {@code NPC_EXAMINE} types, and only
 * the line of the kind that was clicked; any other line, and a line of the other kind, gives nothing and forgets nothing.
 *
 * <p>Choice: the click and the chat line both arrive on the client thread, so the reader keeps its one remembered thing
 * without a lock.
 */
final class ExamineReader implements LineReader
{
	/** How many game ticks after the click an examine line still counts as its answer. */
	static final int FRESH_TICKS = 2;

	/** The game's non-breaking space, which a menu target may carry in a name. */
	private static final char NBSP = '\u00a0';
	/** What stands between the name written in front of an examine line and the text. */
	private static final String NAME_END = ": ";
	/** The menu option of an examine click, tags removed. */
	private static final String EXAMINE = "Examine";
	/** " (level-732)": the level a monster's menu target ends with. */
	private static final Pattern LEVEL = Pattern.compile("\\s*\\(level-\\d+\\)\\s*$");

	/** What the last examine click was on. */
	private enum Kind
	{
		NONE,
		ITEM,
		MONSTER
	}

	private final ItemCards itemCards;
	private final CardTables tables;
	private final BooleanSupplier on;
	private final IntSupplier tick;
	private final Supplier<ExamineLine> style;

	/** The kind of thing last examined; {@link Kind#NONE} when nothing is remembered. */
	private Kind kind = Kind.NONE;
	/** The id of the item last examined, while {@link #kind} is an item. */
	private int itemId;
	/** The name of the monster last examined, while {@link #kind} is a monster. */
	private String monster = "";
	/** The game tick the remembered click was made on. */
	private int clickedAt;

	/**
	 * @param itemCards makes the item card
	 * @param tables the bosses' facts, which may not have loaded yet
	 * @param on whether the "Examine cards" setting is on, asked for each line
	 * @param tick the client's game tick count, asked for each click and each line
	 * @param style how an examine line reads, asked for each line
	 */
	ExamineReader(ItemCards itemCards, CardTables tables, BooleanSupplier on, IntSupplier tick, Supplier<ExamineLine> style)
	{
		this.itemCards = itemCards;
		this.tables = tables;
		this.on = on;
		this.tick = tick;
		this.style = style;
	}

	/** Remembers that the item with this id was just examined, and when; it replaces whatever was remembered. */
	void itemExamined(int id)
	{
		kind = Kind.ITEM;
		itemId = id;
		clickedAt = tick.getAsInt();
	}

	/** Remembers that the monster with this name was just examined, and when; it replaces whatever was remembered. */
	void npcExamined(String name)
	{
		kind = Kind.MONSTER;
		monster = name;
		clickedAt = tick.getAsInt();
	}

	/** Forgets what was remembered: the player examined something that gives no card, an object. */
	void otherExamined()
	{
		kind = Kind.NONE;
	}

	/**
	 * The line as it should read: with "Examine cards" on, the style {@link ExamineLine#NAME_FIRST} and a line that answers
	 * the click remembered (the kind and the freshness {@link #read} asks for), the thing's name, ": " and the message as it
	 * came, such as "Law rune: Used for teleport spells." (an item's name is its canonical item's, {@link
	 * ItemCards#nameOf}); otherwise the message unchanged, as it is too when the thing has no name. It remembers and forgets
	 * nothing. A null message gives null.
	 */
	String label(ChatMessageType type, String message)
	{
		if (message == null || !on.getAsBoolean() || style.get() != ExamineLine.NAME_FIRST || !asked(type))
		{
			return message;
		}
		final String name = examinedName();
		return name == null || name.isEmpty() ? message : name + NAME_END + message;
	}

	/** The name of the thing remembered: the item's, null when it has none, or the monster's. */
	private String examinedName()
	{
		return kind == Kind.ITEM ? itemCards.nameOf(itemId) : monster;
	}

	/**
	 * The card for the thing last examined, or none. With "Examine cards" off, nothing. An {@code ITEM_EXAMINE} line while
	 * an item is remembered from at most {@link #FRESH_TICKS} ticks ago gives the item's card, and an {@code NPC_EXAMINE}
	 * line while a monster is remembered from as recently gives the monster's; the thing is then forgotten. The card's
	 * words are the name alone when the text starts with the thing's name and ": " (the line {@link #label} wrote), else the
	 * whole text. A remembered thing from the future (the tick count went back, as at a new login) or older than the window
	 * gives nothing.
	 *
	 * <p>Choice: a monster the table lacks, or a table that has not loaded, still gives its card: no facts, and the wiki's
	 * picture, which every name is asked for.
	 */
	@Override
	public List<HoverCard> read(ChatMessageType type, String message)
	{
		if (message == null || !on.getAsBoolean() || !asked(type))
		{
			return Collections.emptyList();
		}
		final String plain = ChatText.plain(message);
		if (plain.isEmpty())
		{
			return Collections.emptyList();
		}
		final Kind examined = kind;
		final String name = examinedName();
		final int end = name != null && !name.isEmpty() && plain.startsWith(name + NAME_END) ? name.length() : plain.length();
		kind = Kind.NONE;
		final HoverCard card;
		if (examined == Kind.ITEM)
		{
			card = itemCards.forId(itemId, 1, plain, 0, end);
		}
		else
		{
			final CardTables.BossInfo info = tables.boss(monster);
			card = new InfoCard(monster, BossCards.facts(info), Collections.<String>emptyList(),
				BossCards.page(info, monster), plain, 0, end, SkillSprites.spriteOf("Combat"), -1, true, true);
		}
		return card == null ? Collections.<HoverCard>emptyList() : Collections.singletonList(card);
	}

	/** Whether a line of this type answers the click remembered: the kind matches and the click is fresh. */
	private boolean asked(ChatMessageType type)
	{
		final boolean matches = kind == Kind.ITEM && type == ChatMessageType.ITEM_EXAMINE
			|| kind == Kind.MONSTER && type == ChatMessageType.NPC_EXAMINE;
		if (!matches)
		{
			return false;
		}
		final int age = tick.getAsInt() - clickedAt;
		return age >= 0 && age <= FRESH_TICKS;
	}

	/**
	 * What the plugin calls on every menu click: an Examine click is told to the reader, any other click is left alone. Only
	 * an option whose words, tags removed, are "Examine" counts. An examine of an item on the ground or in a widget the game
	 * sends as an item action gives the id of the click; of a monster, its name, from the menu entry's NPC when it has one,
	 * else from the menu target with its tags and its trailing "(level-N)" cut; of an object, nothing is remembered and what
	 * was remembered is forgotten. Any other action that carries an item (the inventory, the bank, the worn items, which the
	 * game sends as a widget option) is an item examine too.
	 *
	 * <p>Choice: an Examine click that names nothing the reader can use (a monster with no name, an action with no item)
	 * forgets what was remembered, as an object does, since it is a newer examine than the one remembered.
	 */
	static void clicked(ExamineReader reader, MenuOptionClicked event)
	{
		final String option = event.getMenuOption();
		if (option == null || !EXAMINE.equals(Text.removeTags(option).replace(NBSP, ' ').trim()))
		{
			return;
		}
		final MenuAction action = event.getMenuAction();
		if (action == MenuAction.EXAMINE_ITEM_GROUND)
		{
			reader.itemExamined(event.getId());
		}
		else if (action == MenuAction.EXAMINE_NPC)
		{
			final String name = monsterName(event);
			if (name.isEmpty())
			{
				reader.otherExamined();
			}
			else
			{
				reader.npcExamined(name);
			}
		}
		else if (action == MenuAction.EXAMINE_OBJECT || event.getItemId() < 0)
		{
			reader.otherExamined();
		}
		else
		{
			reader.itemExamined(event.getItemId());
		}
	}

	/**
	 * The name of the monster an examine click was on: the menu entry's NPC's name when it has one, else the menu target
	 * without its tags and its trailing " (level-N)"; trimmed, with a non-breaking space read as a space; empty for none.
	 */
	private static String monsterName(MenuOptionClicked event)
	{
		final MenuEntry entry = event.getMenuEntry();
		final NPC npc = entry == null ? null : entry.getNpc();
		final String named = npc == null ? null : npc.getName();
		if (named != null)
		{
			return Text.removeTags(named).replace(NBSP, ' ').trim();
		}
		final String target = event.getMenuTarget();
		if (target == null)
		{
			return "";
		}
		return LEVEL.matcher(Text.removeTags(target).replace(NBSP, ' ')).replaceFirst("").trim();
	}
}

package com.clanhub;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;

/**
 * The 2hBuilds settings icon, drawn in code: a ring with eight teeth and a hole through the middle, the picture the
 * settings icon of every 2hBuilds plugin shows (STANDARD A4). It is the bank's icon, pulled out of its widget helper so
 * the one picture can be copied into another plugin unchanged; it refers to no class of the plugin it sits in.
 *
 * <p>The ring is a stroke and not a filled disc, so the middle stays transparent and the picture reads as a settings
 * icon at 12 px rather than as a cogged blob. The teeth are eight round-capped spokes every 45 degrees, starting on
 * the ring's own circle so each is rooted in the ring's metal and none reaches into the hole. Every length is a
 * fraction of the size, so the same shape comes out at any size.
 */
final class GearGlyph
{
	/** The number of teeth. */
	static final int TEETH = 8;
	/** The smallest side drawn: below it the hole closes and the teeth merge. */
	static final int MIN_SIZE = 7;

	private GearGlyph()
	{
	}

	/**
	 * A new square icon, transparent except for the ring and its teeth.
	 *
	 * @param size   the icon's side in px; anything under {@value #MIN_SIZE} is raised to it
	 * @param colour the ink; null falls back to the sidebar's quiet grey, {@link ColorScheme#LIGHT_GRAY_COLOR}
	 */
	static ImageIcon icon(int size, Color colour)
	{
		final int s = Math.max(MIN_SIZE, size);
		final BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			g.setColor(colour == null ? ColorScheme.LIGHT_GRAY_COLOR : colour);
			final double centre = s / 2.0;
			// The ring's centre line, the width of its metal, and how far a tooth's centre line reaches - the last
			// one pulled in by half a tooth so the round cap lands inside the icon instead of being clipped.
			final double ring = centre * 0.52;
			final float ringWidth = (float) Math.max(1.5, s * 0.2);
			final float toothWidth = (float) Math.max(1.3, s * 0.16);
			final double toothOut = centre - toothWidth / 2.0 - 0.25;
			g.setStroke(new BasicStroke(ringWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.draw(new Ellipse2D.Double(centre - ring, centre - ring, ring * 2.0, ring * 2.0));
			g.setStroke(new BasicStroke(toothWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			for (int i = 0; i < TEETH; i++)
			{
				final double angle = i * 2.0 * Math.PI / TEETH;
				final double cos = Math.cos(angle);
				final double sin = Math.sin(angle);
				g.draw(new Line2D.Double(centre + cos * ring, centre + sin * ring,
					centre + cos * toothOut, centre + sin * toothOut));
			}
		}
		finally
		{
			g.dispose();
		}
		return new ImageIcon(img);
	}
}

package com.clanhub;

import java.util.List;

/**
 * What the overlay, the painter and the menu need of any card: the words it shows, the line it came from with the
 * place of its words in that line, and its picture. The item card is one; the cards of later lots (quests, kinds of
 * broadcast, drop rates) are others. Pure model: it holds words and numbers and asks the client nothing.
 */
interface HoverCard
{
	/** One label with its value, and a note that follows the value in the label's grey. */
	final class Pair
	{
		/** The label, such as "Price". */
		final String label;
		/** The value, such as "121M". */
		final String value;
		/** What follows the value in the label's grey, such as " (460 each)"; empty when there is none. */
		final String note;

		Pair(String label, String value, String note)
		{
			this.label = label;
			this.value = value;
			this.note = note;
		}
	}

	/** The card's title, in bold at the top. */
	String title();

	/** The card's rows of label and value pairs, under the title; may be empty. */
	List<List<Pair>> rows();

	/**
	 * The description lines a card that is not an item's shows under its rows, already wrapped, one line each; empty for
	 * an item.
	 */
	List<String> notes();

	/** The card's last line: what a right-click does. */
	String hint();

	/** The wiki address "Open wiki" opens. */
	String wikiUrl();

	/**
	 * The title of the wiki page whose first paragraph the card shows under its rows: the name an item is called by, or
	 * a page's name with its underscores read as spaces; what is asked of the wiki, and the only thing that is.
	 */
	String wikiTitle();

	/** The chat line as plain text, what "Copy" puts on the clipboard. */
	String plainLine();

	/** Where the card's words start in {@link #plainLine()}. */
	int start();

	/** Just past the card's last word in {@link #plainLine()}. */
	int end();

	/** The id of the item whose sprite is the card's picture, or -1 when the picture is not an item's. */
	int itemId();

	/** How many of the item the picture shows; 1 when the card has no item. */
	int quantity();

	/** The game's own sprite id for the picture when it is not an item's, or -1. */
	int spriteId();

	/**
	 * Whether the card shows the wiki's own picture of its page in the big picture box, fetched while the "Wiki pictures"
	 * setting is on, with the item or the sprite behind it until it comes; true for the cards of a boss, monster, raid or
	 * chest, false for the rest.
	 */
	boolean wikiPicture();

	/**
	 * Whether the card's words are coloured in the chat at rest. A card that is not marked is quiet: the line keeps the
	 * game's own colour, and the words show themselves only when the mouse is on the line, or under the "Underline
	 * level-ups" setting.
	 */
	boolean marked();
}

package com.clanhub;

import java.awt.image.BufferedImage;
import java.util.function.Consumer;

/**
 * Where a row of the sidebar's recent cards gets its picture: the card's own, which the game's sprite and item managers
 * give and the wiki's pictures sometimes replace. The picture may come at once, later, or not at all, and a picture that
 * loads gives itself twice (blank, then drawn), so the row draws what it is given each time. The plugin backs it with the
 * managers; a test backs it with a source that gives nothing.
 */
interface IconSource
{
	/**
	 * Gives {@code onIcon} the picture of {@code card}, now or later, on any thread. A card with no picture gives
	 * nothing.
	 *
	 * @param card the card the row shows
	 * @param onIcon what takes the picture; it may be called more than once
	 */
	void iconFor(HoverCard card, Consumer<BufferedImage> onIcon);

	/**
	 * Gives {@code onIcon} the game's sprite {@code spriteId}, now or later, on any thread. The how-to's rows ask for the
	 * pictures of the kinds of card (the quest, total level and combat icons) this way. Gives nothing by default.
	 *
	 * @param spriteId the sprite's id
	 * @param onIcon   what takes the picture; it may be called more than once
	 */
	default void sprite(int spriteId, Consumer<BufferedImage> onIcon)
	{
	}

	/**
	 * Gives {@code onIcon} the picture of the item {@code itemId} at a stack of {@code quantity}, now or later, on any
	 * thread; an item's picture is handed out before it has loaded and again when it has. Gives nothing by default.
	 *
	 * @param itemId   the item's id
	 * @param quantity the stack the picture shows
	 * @param onIcon   what takes the picture; it may be called more than once
	 */
	default void item(int itemId, int quantity, Consumer<BufferedImage> onIcon)
	{
	}
}

package com.clanhub;

import java.net.URLDecoder;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * What the card says about one thing a broadcast line names that is not an item: a quest, a combat achievement task, a
 * pet, a level, a diary tier, a personal best or a kill count. Pure model: it holds the title, one row of facts, the
 * notes (the description, whole), the wiki page, and the line it came from with the place of the thing's name in it; it draws
 * nothing and asks the client nothing. It is the {@link HoverCard} of these: a game sprite for its picture, or an item
 * (a pet's, the clue watch's), or none; the card of a boss, monster, raid or chest also says it wants the wiki's own
 * picture of its page ({@link #wikiPicture}), the sprite or item standing behind it until that comes.
 */
final class InfoCard implements HoverCard
{
	/** The card's last line, the item card's. */
	private static final String HINT = "Right-click: Open wiki | Copy";
	/** The wiki's address for a page, to which the page's name is added. */
	private static final String WIKI = "https://oldschool.runescape.wiki/w/";

	private final String title;
	private final List<List<Pair>> rows;
	private final List<String> notes;
	private final String page;
	private final String line;
	private final int start;
	private final int end;
	private final int spriteId;
	private final int itemId;
	private final boolean marked;
	private final boolean wikiPicture;

	/**
	 * The card with its title, its one row of facts, its notes (the task description, or the unlocks one to a note, for the
	 * painter to set; may be empty), the wiki page to open (the part after {@code /w/}), the plain chat line, where the
	 * thing's name starts and ends in that line, and the game sprite of its picture or -1 for none; the card has no item
	 * for a picture.
	 */
	InfoCard(String title, List<Pair> row, List<String> notes, String page, String line, int start, int end,
		int spriteId)
	{
		this(title, row, notes, page, line, start, end, spriteId, -1);
	}

	/**
	 * The same card with an item for its picture: {@code itemId} is the id of the item whose sprite it shows (a pet's, the
	 * clue watch's), or -1 for none.
	 */
	InfoCard(String title, List<Pair> row, List<String> notes, String page, String line, int start, int end,
		int spriteId, int itemId)
	{
		this(title, row, notes, page, line, start, end, spriteId, itemId, true);
	}

	/**
	 * The same card with {@code marked} said: false makes it a quiet one, whose words the chat does not colour (the level
	 * and XP phrases); the other constructors make a marked card.
	 */
	InfoCard(String title, List<Pair> row, List<String> notes, String page, String line, int start, int end,
		int spriteId, int itemId, boolean marked)
	{
		this(title, row, notes, page, line, start, end, spriteId, itemId, marked, false);
	}

	/**
	 * The fullest card: {@code wikiPicture} true makes it show the wiki's own picture of its page in the big picture box
	 * (the card of a boss, monster, raid or chest), with the item or the sprite behind it until the picture comes; the
	 * other constructors make a card that does not.
	 */
	InfoCard(String title, List<Pair> row, List<String> notes, String page, String line, int start, int end,
		int spriteId, int itemId, boolean marked, boolean wikiPicture)
	{
		this.wikiPicture = wikiPicture;
		this.marked = marked;
		this.itemId = itemId;
		this.title = title;
		this.rows = Collections.singletonList(Collections.unmodifiableList(new ArrayList<>(row)));
		this.notes = Collections.unmodifiableList(new ArrayList<>(notes));
		this.page = page;
		this.line = line;
		this.start = start;
		this.end = end;
		this.spriteId = spriteId;
	}

	/**
	 * The wiki page for a name: spaces as underscores, then percent-encoded as UTF-8 so an apostrophe, an ampersand or a
	 * bracket reaches the wiki whole ("Lumbridge & Draynor Diary" is "Lumbridge_%26_Draynor_Diary"); a dot is left as it
	 * is, as the wiki's own addresses leave it.
	 */
	static String pageFor(String name)
	{
		return URLEncoder.encode(name.replace(' ', '_'), StandardCharsets.UTF_8).replace("+", "%20");
	}

	/** The card's title. */
	@Override
	public String title()
	{
		return title;
	}

	/** The card's one row of facts. */
	@Override
	public List<List<Pair>> rows()
	{
		return rows;
	}

	/** The notes under the row: the task description, or the level unlocks one to a note, set by the painter as a
	 * paragraph or a numbered list; empty for most kinds. */
	@Override
	public List<String> notes()
	{
		return notes;
	}

	/** The card's last line: what a right-click does, the same as the item card's. */
	@Override
	public String hint()
	{
		return HINT;
	}

	/** The wiki's page for the thing the card is about. */
	@Override
	public String wikiUrl()
	{
		return WIKI + page;
	}

	/**
	 * The wiki page's title for the card's paragraph: the page with its percent-encoding undone and its underscores read
	 * as spaces ("Dragon_Slayer_II" is "Dragon Slayer II", "Why_Cook%3F" is "Why Cook?").
	 *
	 * <p>Choice: a page whose percent-encoding is malformed keeps it as written, with its underscores read as spaces.
	 */
	@Override
	public String wikiTitle()
	{
		try
		{
			return URLDecoder.decode(page, StandardCharsets.UTF_8).replace('_', ' ');
		}
		catch (IllegalArgumentException e)
		{
			return page.replace('_', ' ');
		}
	}

	/** The chat line as plain text, what "Copy" puts on the clipboard. */
	@Override
	public String plainLine()
	{
		return line;
	}

	/** Where the thing's name starts in the line. */
	@Override
	public int start()
	{
		return start;
	}

	/** Just past the thing's name in the line. */
	@Override
	public int end()
	{
		return end;
	}

	/** The id of the item whose sprite is the card's picture (a pet's, the clue watch's), or -1 when it has none. */
	@Override
	public int itemId()
	{
		return itemId;
	}

	/** No item, so no stack: 1. */
	@Override
	public int quantity()
	{
		return 1;
	}

	/** The game sprite of the card's picture, or -1 when it has none. */
	@Override
	public int spriteId()
	{
		return spriteId;
	}

	/** Whether the card shows the wiki's own picture of its page: true for a boss, monster, raid or chest card. */
	@Override
	public boolean wikiPicture()
	{
		return wikiPicture;
	}

	/** Whether the card's words are coloured in the chat; false for the quiet level and XP cards. */
	@Override
	public boolean marked()
	{
		return marked;
	}
}

package com.clanhub;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.util.QuantityFormatter;

/**
 * What the card says about one item named in a chat line: the item, how many, its prices, and the line it came from
 * with the place of the name in it. Pure model: it holds numbers and words and makes the card's texts and the wiki
 * address; it draws nothing and asks the client nothing. It is the {@link HoverCard} of an item: no notes, and the
 * item's own sprite for its picture.
 */
final class ItemCard implements HoverCard
{
	/** The card's last line. */
	private static final String HINT = "Right-click: Open wiki | Copy";
	/** The wiki's item lookup, to which the id and the name are added. */
	private static final String WIKI_LOOKUP = "https://oldschool.runescape.wiki/w/Special:Lookup?type=item&id=";
	/** What a price or an alch value of nothing reads as. */
	private static final String NONE = "-";

	/** The item's id. */
	final int id;
	/** The item's name. */
	final String name;
	/** How many of the item the line names. */
	final int quantity;
	/** The market price of one, in coins; 0 when the item has none. */
	final long price;
	/** The high alchemy value of one, in coins. */
	final int alch;
	/** The chat line without its tags. */
	final String line;
	/** Where the name starts in {@link #line}. */
	final int start;
	/** Just past the name's last character in {@link #line}. */
	final int end;
	/** The drop sources the card shows, every one the table holds (at most its six) in its order; empty when the table has none. */
	private final List<DropRates.DropSource> drops;

	ItemCard(int id, String name, int quantity, long price, int alch, String line, int start, int end)
	{
		this(id, name, quantity, price, alch, line, start, end, Collections.<DropRates.DropSource>emptyList());
	}

	/**
	 * The card with the item's drop sources in the table's order (the monsters first, the best rate first), or an empty
	 * list for none.
	 *
	 * <p>Choice: the card shows every source the table holds for the item (the table keeps at most six) in the table's
	 * order, none reversed, so the best monster leads; the card does not cut the list and says nothing of a rest.
	 */
	ItemCard(int id, String name, int quantity, long price, int alch, String line, int start, int end,
		List<DropRates.DropSource> drops)
	{
		this.drops = Collections.unmodifiableList(new ArrayList<>(drops));
		this.id = id;
		this.name = name;
		this.quantity = quantity;
		this.price = price;
		this.alch = alch;
		this.line = line;
		this.start = start;
		this.end = end;
	}

	/** The card's title: the name, with "x10" after it for a stack. */
	@Override
	public String title()
	{
		return quantity > 1 ? name + " x" + quantity : name;
	}

	/**
	 * The card's rows of label and value pairs: the price and the high alch value, and under them one row for each drop
	 * source the table holds, at most its six, each a single pair with the source's name as its label and the rate as
	 * its value ("Abyssal demon", "1/512"), so a painter can set the name at the left and the rate at the right. For a
	 * stack the price is the total with the price of one after it, and the alch value is the total; a price of nothing
	 * reads "-".
	 */
	@Override
	public List<List<Pair>> rows()
	{
		final String each = quantity > 1 && price > 0 ? " (" + stackSize(price) + " each)" : "";
		final Pair priced = new Pair("Price", price > 0 ? stackSize(price * quantity) : NONE, each);
		final Pair alched = new Pair("High alch", alch > 0 ? stackSize((long) alch * quantity) : NONE, "");
		final List<List<Pair>> rows = new ArrayList<>();
		rows.add(Arrays.asList(priced, alched));
		for (final DropRates.DropSource source : drops)
		{
			rows.add(Collections.singletonList(new Pair(source.from, source.rate, "")));
		}
		return rows;
	}

	/** An item has no description lines. */
	@Override
	public List<String> notes()
	{
		return Collections.emptyList();
	}

	/** The card's last line: what a right-click does. */
	@Override
	public String hint()
	{
		return HINT;
	}

	/**
	 * The wiki's lookup page for the item, by id and name.
	 *
	 * <p>Choice: the name is percent-encoded in full, a space as %20 (not +), so a name with an apostrophe or a bracket
	 * reaches the wiki whole.
	 */
	@Override
	public String wikiUrl()
	{
		return WIKI_LOOKUP + id + "&name=" + URLEncoder.encode(name, StandardCharsets.UTF_8).replace("+", "%20");
	}

	/** The wiki page's title for the card's paragraph: the item's name, which the wiki's redirects resolve. */
	@Override
	public String wikiTitle()
	{
		return name;
	}

	/** The chat line as plain text, what "Copy" puts on the clipboard. */
	@Override
	public String plainLine()
	{
		return line;
	}

	/** Where the item's name starts in the line. */
	@Override
	public int start()
	{
		return start;
	}

	/** Just past the item's name in the line. */
	@Override
	public int end()
	{
		return end;
	}

	/** The item's id: its sprite is the card's picture. */
	@Override
	public int itemId()
	{
		return id;
	}

	/** How many of the item the line names. */
	@Override
	public int quantity()
	{
		return quantity;
	}

	/** An item's picture is its item sprite, never a game sprite. */
	@Override
	public int spriteId()
	{
		return -1;
	}

	/** An item's picture is its own sprite, never the wiki's picture of a page: false. */
	@Override
	public boolean wikiPicture()
	{
		return false;
	}

	/** An item's name is coloured in the chat. */
	@Override
	public boolean marked()
	{
		return true;
	}

	/** A number the way the game writes a stack: 121M, 25.2M, 123K, 4,600. */
	private static String stackSize(long value)
	{
		return QuantityFormatter.quantityToStackSize(value);
	}
}

package com.clanhub;

import java.util.Collections;
import java.util.List;
import java.util.Locale;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;

/**
 * The one place an item card is made: it turns an item's name, with where the name sits in a chat line, into an
 * {@link ItemCard} with the item's id, its market price and its high alchemy value from the item manager, and the item's
 * drop sources from the {@link DropRates} table when it has any. The id comes from the item manager's price list, and,
 * when that does not know the name (a pet and the other untradeables have no price), from the {@link ItemNameIndex}. Every
 * item manager lookup is the item manager's, so a call belongs on the client thread, the caller's.
 */
class ItemCards
{
	private final ItemManager itemManager;
	/** The drop rate table, or null for none. */
	private final DropRates dropRates;
	/** The names of every real item, or null for none; asked when the price list does not know a name. */
	private final ItemNameIndex index;

	/** Cards without drop rates and without the names index: no table, no index. */
	ItemCards(ItemManager itemManager)
	{
		this(itemManager, null, null);
	}

	/** Cards with the drop rates of {@code dropRates}, which may still be loading, and no names index. */
	ItemCards(ItemManager itemManager, DropRates dropRates)
	{
		this(itemManager, dropRates, null);
	}

	/** Cards with the drop rates of {@code dropRates} and the names of {@code index}, either of which may still be loading. */
	ItemCards(ItemManager itemManager, DropRates dropRates, ItemNameIndex index)
	{
		this.itemManager = itemManager;
		this.dropRates = dropRates;
		this.index = index;
	}

	/**
	 * The id of the item called {@code name}: the first search result whose name equals {@code name} ignoring case (a
	 * result that only starts with it, such as "Dragon claws (or)", does not count), else the id the names index holds for
	 * the lowercase name, else -1.
	 *
	 * <p>Choice: a null name has no id.
	 */
	int idOf(String name)
	{
		if (name == null)
		{
			return -1;
		}
		for (final ItemPrice result : itemManager.search(name))
		{
			if (name.equalsIgnoreCase(result.getName()))
			{
				return result.getId();
			}
		}
		final Integer indexed = index == null ? null : index.idOf(name.toLowerCase(Locale.ROOT));
		return indexed == null ? -1 : indexed;
	}

	/**
	 * The card for the item called {@code name}, or null when no item has that name ({@link #idOf} gives -1). The card's
	 * price is the item manager's, which is 0 for an item that has none, and its drops are the sources {@link
	 * DropRates#lookup} gives for the name, of which the card shows four and counts the rest, or none when there is no
	 * table.
	 *
	 * <p>Choice: a null name gives no card, as an unknown one does.
	 */
	HoverCard forName(String name, int quantity, String plainLine, int start, int end)
	{
		final int id = idOf(name);
		if (id < 0)
		{
			return null;
		}
		final long price = itemManager.getItemPrice(id);
		final int alch = itemManager.getItemComposition(id).getHaPrice();
		return new ItemCard(id, name, quantity, price, alch, plainLine, start, end, sources(name));
	}

	/**
	 * The card for the item with the id {@code id}, or null when the item has no name. The id is made canonical first (a
	 * noted item or a placeholder gives the item itself), and the card's name, price and high alchemy value are the canonical
	 * item's, its drops the sources {@link DropRates#lookup} gives for that name, as {@link #forName} makes them; an examined
	 * item is asked for this way, since its examine text names nothing.
	 *
	 * <p>Choice: a name that is null, empty or "null" in any case (the game's name for an id it does not have) gives no card.
	 */
	HoverCard forId(int id, int quantity, String plainLine, int start, int end)
	{
		final String name = nameOf(id);
		if (name == null)
		{
			return null;
		}
		final int canonical = itemManager.canonicalize(id);
		final ItemComposition composition = itemManager.getItemComposition(canonical);
		final long price = itemManager.getItemPrice(canonical);
		return new ItemCard(canonical, name, quantity, price, composition.getHaPrice(), plainLine, start, end, sources(name));
	}

	/**
	 * The name of the item with the id {@code id}: the canonical item's composition name (a noted item or a placeholder
	 * gives the item itself), or null when the item has none.
	 *
	 * <p>Choice: a name that is null, empty or "null" in any case (the game's name for an id it does not have) is no name.
	 */
	String nameOf(int id)
	{
		final ItemComposition composition = itemManager.getItemComposition(itemManager.canonicalize(id));
		final String name = composition == null ? null : composition.getName();
		if (name == null || name.isEmpty() || "null".equalsIgnoreCase(name))
		{
			return null;
		}
		return name;
	}

	/**
	 * The rate of the first source the table gives for the name, as the table writes it ("1/4000"), or an empty text when
	 * the table has not loaded, does not hold the name, or has nothing for it. It reads the sources the way {@link
	 * #forName} does, so the name's case counts the same; a pet's card asks it for the pet's own rate.
	 */
	String rateOf(String name)
	{
		final List<DropRates.DropSource> found = sources(name);
		return found.isEmpty() ? "" : found.get(0).rate;
	}

	/**
	 * The sources of the item, the table's list, or an empty one.
	 *
	 * <p>Choice: a table that has not loaded is not asked, so a card made in the first second after start-up is the card of
	 * lot 1.
	 */
	private List<DropRates.DropSource> sources(String name)
	{
		if (dropRates == null || !dropRates.loaded())
		{
			return Collections.emptyList();
		}
		return dropRates.lookup(name);
	}
}

package com.clanhub;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

/**
 * The names of every item in the game, lowercase, with each name's item id: the item cards' way to an id the price list
 * lacks (a new item, a pet). The game has tens of thousands of items and reading them all at once would stall a frame,
 * so the plugin builds the index a slice at a time, {@link #buildSome} on each game tick, until every id has been read.
 * Every real item is kept, tradeable or not: not a noted copy, not a placeholder, not "null", not a name under five
 * characters. It is read and built on the client thread, the caller's, so it is not synchronized.
 */
final class ItemNameIndex
{
	/** The shortest name kept, so "bow" never matches and "bones" does. */
	private static final int MIN_LENGTH = 5;

	/** The item id by lowercase name; the first id seen for a name stays. */
	private final Map<String, Integer> ids = new HashMap<>();
	/** The next item id to read. */
	int next;
	/** The client's item count as {@link #buildSome} last read it; -1 before the first call. */
	private int total = -1;

	/**
	 * Reads the item ids from {@link #next} up to {@code count} of them, never past the client's item count, and keeps
	 * the items that pass: not a noted item, not a placeholder, a name that is not "null" and has five characters or
	 * more. The first id seen for a lowercase name stays.
	 *
	 * <p>Choice: the item count is read on every call, so a call after the index is complete reads nothing; the index is
	 * not complete before its first call, whatever the item count. An item that cannot be traded or alched stays in:
	 * a pet and the other untradeables have no price, but a card needs their ids, for their pictures and their names.
	 */
	void buildSome(Client client, ItemManager itemManager, int count)
	{
		total = client.getItemCount();
		final int stop = (int) Math.min((long) next + count, total);
		for (; next < stop; next++)
		{
			final ItemComposition composition = itemManager.getItemComposition(next);
			if (composition != null && keeps(composition))
			{
				add(next, composition.getName());
			}
		}
	}

	/** Stores a name with its id, unless the lowercase name is already there, in which case the first one stays. */
	void add(int id, String name)
	{
		final String lower = name.toLowerCase(Locale.ROOT);
		if (idOf(lower) == null)
		{
			ids.put(lower, id);
		}
	}

	/** Whether every item id up to the client's item count has been read. */
	boolean complete()
	{
		return total >= 0 && next >= total;
	}

	/** How many names the index holds. */
	int size()
	{
		return ids.size();
	}

	/** The item id for a lowercase name, or null when the index does not know it. */
	Integer idOf(String lowercaseName)
	{
		return ids.get(lowercaseName);
	}

	/** Whether an item is one the index keeps. */
	private static boolean keeps(ItemComposition composition)
	{
		final String name = composition.getName();
		return composition.getNote() == -1
			&& composition.getPlaceholderTemplateId() == -1
			&& name != null
			&& name.length() >= MIN_LENGTH
			&& !"null".equalsIgnoreCase(name);
	}
}

package com.clanhub;

import java.util.List;
import net.runelite.api.ChatMessageType;

/**
 * Reads one chat line for the cards it holds. The plugin keeps a list of readers and asks each of them about every
 * chat message; a later lot adds a reader of its own and one line to that list.
 */
interface LineReader
{
	/**
	 * The cards the line holds, in the order their words stand in it; an empty list when it holds nothing. {@code message}
	 * is the chat text as the game sends it, tags and all.
	 */
	List<HoverCard> read(ChatMessageType type, String message);
}

package com.clanhub;

import com.clanhub.ClanHubConfig.CardTheme;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.LinearGradientPaint;
import java.awt.Paint;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.awt.geom.Arc2D;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * The scenes of the six nature card themes, painted on the {@link Graphics2D} that {@link SceneSky} makes for a card's
 * ground. Each is a picture inside a border, the picture 3 px in from the card's edge with rounded corners, laid in
 * layers from the back to the front, with a dark veil over it (heavier at the left, where the words are) at the layer
 * the scene says:
 *
 * <ul>
 * <li>Forest: a green night with four soft rays of light from the top right, two rows of pines and a mist along the
 * bottom, vines hanging in the corners at the top, fireflies in the right two thirds; a wooden frame with a leaf in
 * each corner.</li>
 * <li>Ocean: a blue deep that darkens downwards, five soft rays, a few ripples of light at the top, a school of fish
 * and a kelp forest at the right, coral at the left, bubbles at the right; a glowing pale blue frame with a pearl in
 * each corner.</li>
 * <li>Autumn: a copper dusk with a low sun at the right, a bare branch reaching in from the top right, a pile of maple
 * leaves along the bottom and a few falling; an orange frame with a maple leaf in each corner.</li>
 * <li>Sakura: a purple night with a pale moon at the top right, a torii gate at the bottom, a branch heavy with
 * blossom reaching in from the top right and petals drifting down; a glowing pink frame.</li>
 * <li>Garden: a green day with a warm sun at the top right, soft rays, a white picket fence along the bottom with
 * tulips and daisies in front of it, a rose vine up the right side and two butterflies; a white frame with a rose in
 * each corner.</li>
 * <li>Lavender: a dusk sky that lightens toward the horizon, a few stars, a lone tree on the horizon, a field of
 * lavender in rows that grow larger toward the front, a few poppies and fireflies; a glowing lilac frame.</li>
 * </ul>
 *
 * <p>Choice: no blur is used. A soft edge or a glow is a radial gradient shaped as the blur would shape it, or a few
 * strokes of falling alpha, so each scene is plain Java2D. Where the picture is laid with an {@link AlphaComposite#Src
 * Src} layer, shapes that overlap replace each other and so do not add up their alpha. The random places (the pines, the
 * leaves, the fireflies, the petals) are laid from fixed seeds, so the same size gives the same picture.
 */
final class NatureScenes
{
	/** How far in from the card's edge the picture starts, in px, for the border to frame it. */
	private static final int INSET = 3;

	/** The least width or height of a picture, in px; a card smaller than that and its inset is a plain gradient. */
	private static final int MIN_SIDE = 24;

	private static final double TAU = 2 * Math.PI;

	private NatureScenes()
	{
	}

	/**
	 * Paints {@code theme}'s whole ground, {@code width} by {@code height} px with its top-left corner at the graphics'
	 * origin: the picture with its gradient and its layers, its veil, the border and a 1 px edge in the theme's edge
	 * colour. A card too small for the picture gets the gradient and the edge alone.
	 */
	static void paint(CardTheme theme, Graphics2D g, int width, int height)
	{
		final int w = width - 2 * INSET;
		final int h = height - 2 * INSET;
		if (w < MIN_SIDE || h < MIN_SIDE)
		{
			g.setPaint(new GradientPaint(0f, 0f, SceneSky.groundTop(theme), 0f, Math.max(1, height - 1),
				SceneSky.groundBottom(theme)));
			g.fillRect(0, 0, width, height);
			edge(g, theme, width, height);
			return;
		}
		final AffineTransform origin = g.getTransform();
		final Shape clip = g.getClip();
		g.translate(INSET, INSET);
		switch (theme)
		{
			case FOREST:
				forest(g, w, h);
				break;
			case OCEAN:
				ocean(g, w, h);
				break;
			case AUTUMN:
				autumn(g, w, h);
				break;
			case SAKURA:
				sakura(g, w, h);
				break;
			case GARDEN:
				garden(g, w, h);
				break;
			default:
				lavender(g, w, h);
				break;
		}
		g.setClip(clip);
		g.setTransform(origin);
		switch (theme)
		{
			case FOREST:
				forestBorder(g, width, height);
				break;
			case OCEAN:
				oceanBorder(g, width, height);
				break;
			case AUTUMN:
				autumnBorder(g, width, height);
				break;
			case SAKURA:
				sakuraBorder(g, width, height);
				break;
			case GARDEN:
				gardenBorder(g, width, height);
				break;
			default:
				lavenderBorder(g, width, height);
				break;
		}
		edge(g, theme, width, height);
	}

	// ------------------------------------------------------------------------------------------------ the six scenes

	/** Forest: rays, two rows of pines, mist, the veil, vines and fireflies. */
	private static void forest(Graphics2D g, int w, int h)
	{
		ground(g, w, h, 5, new float[] {0f, 0.55f, 1f}, rgb(22, 54, 40), rgb(12, 34, 22), rgb(6, 16, 10));
		final double[] rays = {w - 40, w - 90, w - 140, w - 200};
		for (int i = 0; i < rays.length; i++)
		{
			final double x = rays[i];
			soft(g, poly(x - 8, 0, x + 14, 0, x - 30, h, x - 70, h), rgb(210, 240, 150, i % 2 == 1 ? 26 : 38), 3);
		}
		final Random random = new Random(3);
		final Layer far = new Layer(w, h);
		for (int x = -10; x < w + 20; x += 14)
		{
			pine(far.g, x + u(random, -4, 4), h + 4, u(random, 34, 52), u(random, 9, 13), rgb(28, 70, 54, 150));
		}
		far.over(g);
		final double top = h - 44;
		final float[] at = new float[9];
		final Color[] colours = new Color[9];
		for (int i = 0; i < 9; i++)
		{
			at[i] = i / 8f;
			final double y = top + i / 8.0 * 36;
			colours[i] = rgb(150, 200, 170, i == 0 ? 0 : (int) Math.round(60 * phi((y - (h - 26)) / 8)));
		}
		g.setPaint(new LinearGradientPaint(0f, (float) top, 0f, (float) (top + 36), at, colours));
		g.fill(new Rectangle2D.Double(0, top, w, h - top));
		final Layer near = new Layer(w, h);
		for (int x = -6; x < 60; x += 16)
		{
			pine(near.g, x + u(random, -3, 3), h + 6, u(random, 46, 70), u(random, 12, 17), rgb(8, 26, 16, 240));
		}
		for (int x = w - 70; x < w + 10; x += 15)
		{
			pine(near.g, x + u(random, -3, 3), h + 6, u(random, 46, 70), u(random, 12, 17), rgb(8, 26, 16, 240));
		}
		near.over(g);
		SceneSky.veil(g, w, h, 70, 20);
		final Layer vines = new Layer(w, h);
		final Color[] greens = {rgb(46, 120, 52, 240), rgb(70, 150, 60, 230), rgb(32, 96, 44, 245),
			rgb(100, 170, 70, 220)};
		final double[] hangs = {w - 22, w - 48, w - 78, w - 104, 18, 40};
		for (final double vx : hangs)
		{
			final double length = u(random, 14, 34);
			vines.g.setColor(rgb(40, 70, 30, 230));
			vines.g.setStroke(new BasicStroke(1f));
			vines.g.draw(new Line2D.Double(vx, 0, vx + u(random, -3, 3), length));
			for (int k = 0; k < (int) (length / 4); k++)
			{
				leaf(vines.g, vx + (random.nextBoolean() ? -3 : 3), 2 + k * 4, u(random, 3.5, 5.5), u(random, 0.3, 2.8),
					greens[random.nextInt(greens.length)]);
			}
		}
		for (int i = 0; i < 18; i++)
		{
			leaf(vines.g, u(random, w - 120, w), u(random, -4, 8), u(random, 5, 9), u(random, 0, Math.PI),
				greens[random.nextInt(greens.length)]);
		}
		vines.over(g);
		final double[][] flies = new double[22][];
		for (int i = 0; i < flies.length; i++)
		{
			flies[i] = new double[] {u(random, w * 0.3, w - 6), u(random, h * 0.35, h - 8)};
			glow(g, flies[i][0], flies[i][1], 4, 4, rgb(220, 255, 110, 140), 2.2);
		}
		g.setColor(rgb(250, 255, 170));
		for (final double[] fly : flies)
		{
			g.fill(new Ellipse2D.Double(fly[0] - 0.8, fly[1] - 0.8, 1.6, 1.6));
		}
	}

	/** Ocean: rays, ripples, a school of fish, kelp and coral, the veil and bubbles. */
	private static void ocean(Graphics2D g, int w, int h)
	{
		ground(g, w, h, 5, new float[] {0f, 0.35f, 1f}, rgb(30, 120, 170), rgb(12, 70, 120), rgb(2, 16, 40));
		final double[] rayAt = {w * 0.12, w * 0.32, w * 0.55, w * 0.74, w * 0.92};
		for (int i = 0; i < rayAt.length; i++)
		{
			final double x = rayAt[i];
			soft(g, poly(x - 6, 0, x + 8, 0, x + 46, h, x + 4, h), rgb(190, 240, 255, i % 2 == 1 ? 34 : 48), 4);
		}
		final Random random = new Random(5);
		for (int i = 0; i < 46; i++)
		{
			final double x = u(random, 0, w);
			final double y = u(random, 0, 26);
			final Path2D.Double ripple = new Path2D.Double();
			for (int k = 0; k < 7; k++)
			{
				final double t = k / 6.0 * TAU;
				final double px = x + u(random, -1, 1) + 6 * Math.cos(t);
				final double py = y + 3 * Math.sin(t);
				if (k == 0)
				{
					ripple.moveTo(px, py);
				}
				else
				{
					ripple.lineTo(px, py);
				}
			}
			// Two strokes, a faint wide one and a finer one on it, give the ripple the soft edge a blur would.
			g.setColor(rgb(220, 250, 255, 28));
			g.setStroke(new BasicStroke(2.4f));
			g.draw(ripple);
			g.setColor(rgb(220, 250, 255, 52));
			g.setStroke(new BasicStroke(1f));
			g.draw(ripple);
		}
		final Layer fish = new Layer(w, h);
		fish.g.setColor(rgb(10, 40, 70, 170));
		for (int i = 0; i < 14; i++)
		{
			final double fx = w - 150 + (i % 7) * 13 + u(random, -3, 3);
			final double fy = 38 + (i / 7) * 10 + 0.8 * (i % 7) + u(random, -2, 2);
			fish.g.fill(new Ellipse2D.Double(fx - 4, fy - 1.5, 8, 3));
			fish.g.fill(poly(fx + 3.5, fy, fx + 7, fy - 2.5, fx + 7, fy + 2.5));
		}
		fish.over(g);
		final Layer floor = new Layer(w, h);
		floor.g.setStroke(new BasicStroke(2f));
		for (int kx = w - 60; kx < w - 4; kx += 7)
		{
			final Path2D.Double stalk = new Path2D.Double();
			final List<double[]> points = new ArrayList<>();
			final int stop = (int) (h - u(random, 40, 70));
			for (int y = h; y > stop; y -= 3)
			{
				points.add(new double[] {kx + 3 * Math.sin(y / 7.0 + kx), y});
			}
			for (int i = 0; i < points.size(); i++)
			{
				if (i == 0)
				{
					stalk.moveTo(points.get(i)[0], points.get(i)[1]);
				}
				else
				{
					stalk.lineTo(points.get(i)[0], points.get(i)[1]);
				}
			}
			floor.g.setColor(rgb(20, 110, 70, 220));
			floor.g.draw(stalk);
			for (int i = 0; i < points.size(); i += 3)
			{
				leaf(floor.g, points.get(i)[0] + 3, points.get(i)[1], 3, 0.5, rgb(40, 150, 90, 200));
			}
		}
		floor.g.setColor(rgb(240, 110, 120, 230));
		for (final int cx : new int[] {14, 34, 52})
		{
			for (int k = 0; k < 5; k++)
			{
				final double a = -Math.PI / 2 + (k - 2) * 0.45;
				floor.g.draw(new Line2D.Double(cx, h, cx + 14 * Math.cos(a), h + 14 * Math.sin(a)));
			}
		}
		floor.over(g);
		SceneSky.veil(g, w, h, 70, 15);
		final Layer bubbles = new Layer(w, h);
		bubbles.g.setStroke(new BasicStroke(1f));
		for (int i = 0; i < 22; i++)
		{
			final double x = u(random, w - 90, w - 6);
			final double y = u(random, 6, h - 6);
			final double s = u(random, 1.2, 4.5);
			bubbles.g.setColor(rgb(210, 245, 255, 190));
			bubbles.g.draw(new Ellipse2D.Double(x - s + 0.5, y - s + 0.5, 2 * s - 1, 2 * s - 1));
			bubbles.g.setColor(rgb(255, 255, 255, 220));
			bubbles.g.fill(new Ellipse2D.Double(x - s * 0.55, y - s * 0.6, s * 0.4, s * 0.4));
		}
		bubbles.over(g);
	}

	/** Autumn: the low sun, a bare branch, a pile of maple leaves, the veil and leaves in the air. */
