package com.clanhub;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The two short phrases a recent-cards row shows under its title: who the line is about and what kind of card it gave.
 * Pure: a row's plain chat line in, words out, nothing read from the client.
 *
 * <p>{@link #who} is the text before the first broadcast phrase (" received a ", " has completed ", " has reached ",
 * " feels like " and the like, never a bare " has ", which an examine text may hold), as a broadcast starts with the
 * player's name ("Klar received a drop: ..."), and "You" for a line that has none of them, which is the player's own
 * line ("Valuable drop: ...", "Your Vorkath kill count is: 420.", an examine line).
 *
 * <p>{@link #what} is the kind, the first of these that fits, matched ignoring case:
 * <ul>
 * <li>"drop": "Dragonrains received a drop: Broken dragon hook (773,703 coins)." or "Valuable drop: ...", "Untradeable drop: ..."</li>
 * <li>"clue item": "Klar received a clue item: Ranger boots (25,296,193 coins)"</li>
 * <li>"collection log": "Klar received a new collection log item: Abyssal whip (1/484)" or "New item added to your collection log: ..."</li>
 * <li>"raid loot": "Klar received special loot from a raid: Twisted bow."</li>
 * <li>"quest": "aetzli has completed a quest: Observatory Quest"</li>
 * <li>"medium task", "easy task" and the other tiers, in lower case: "GMucker has completed a medium combat task: Smite Fight."</li>
 * <li>"pet": "Clipper has a funny feeling like he's being followed: Pet snakeling at 2,678 killcount.", "... sneaking into ...", "... acquired something special ..."</li>
 * <li>"XP milestone": "FishStonks has reached 43,000,000 XP in Strength."</li>
 * <li>"level-up": "aetzli has reached Crafting level 50." or the player's own "Congratulations, you've just advanced your Thieving level. You are now level 77."</li>
 * <li>"diary": "Klar has completed the Elite Ardougne diary."</li>
 * <li>"personal best": "Klar has achieved a new Vorkath personal best: 2:28"</li>
 * <li>"kill count": "Your Vorkath kill count is: 420."</li>
 * <li>"examined": any other line whose {@link #who} is "You", such as "Law rune: Used for teleport spells."</li>
 * <li>"" for anything else.</li>
 * </ul>
 */
final class RowWords
{
	/** What {@link #who} says for a line that names no player. */
	static final String YOU = "You";

	/** The words after a player's name in a broadcast: the first of them ends the name. */
	private static final String[] NAME_ENDS = {" received a ", " received special ", " has completed ", " has reached ",
		" has achieved ", " has a funny feeling ", " feels something ", " feels like "};
	/** "medium combat task": the tier, which {@link #what} says in lower case with "task". */
	private static final Pattern TASK = Pattern.compile(
		"\\b(easy|medium|hard|elite|master|grandmaster) combat task", Pattern.CASE_INSENSITIVE);

	private RowWords()
	{
	}

	/** Who the line is about: see the class comment. A null line gives "". */
	static String who(String line)
	{
		if (line == null)
		{
			return "";
		}
		int first = -1;
		for (final String end : NAME_ENDS)
		{
			final int at = line.indexOf(end);
			if (at >= 0 && (first < 0 || at < first))
			{
				first = at;
			}
		}
		return first < 0 ? YOU : line.substring(0, first).trim();
	}

	/** What kind of card the line gave: see the class comment. A null line gives "". */
	static String what(String line)
	{
		if (line == null)
		{
			return "";
		}
		final String lower = line.toLowerCase(Locale.ROOT);
		if (lower.contains("received a drop") || lower.contains("valuable drop") || lower.contains("untradeable drop"))
		{
			return "drop";
		}
		if (lower.contains("received a clue item"))
		{
			return "clue item";
		}
		if (lower.contains("new collection log item") || lower.contains("new item added to your collection log"))
		{
			return "collection log";
		}
		if (lower.contains("special loot from a raid"))
		{
			return "raid loot";
		}
		if (lower.contains("completed a quest"))
		{
			return "quest";
		}
		final Matcher task = TASK.matcher(line);
		if (task.find())
		{
			return task.group(1).toLowerCase(Locale.ROOT) + " task";
		}
		if (lower.contains("being followed") || lower.contains("sneaking into") || lower.contains("acquired something special"))
		{
			return "pet";
		}
		if (lower.contains(" xp in "))
		{
			return "XP milestone";
		}
		if (lower.contains("level")
			&& (lower.contains("has reached") || lower.contains("just advanced your") || lower.contains("just advanced a")))
		{
			return "level-up";
		}
		if (lower.contains(" diary"))
		{
			return "diary";
		}
		if (lower.contains("personal best"))
		{
			return "personal best";
		}
		if (lower.contains("count is"))
		{
			return "kill count";
		}
		return YOU.equals(who(line)) ? "examined" : "";
	}
}

package com.clanhub;

import com.clanhub.ClanHubConfig.CardTheme;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The ground of the twelve scene card themes (Forest, Ocean, Autumn, Sakura, Steampunk, Cyberpunk, Synthwave, Volcano,
 * Runic, Spooky, Garden and Lavender): a vertical gradient from the theme's top colour to its bottom colour, the theme's
 * scene over it and a thin edge, all painted into one image of the card's size. Pure: a theme and a size in, an image
 * out; nothing is read from the client.
 *
 * <p>The scene itself is not painted here: {@link NatureScenes} paints the six nature themes (Forest, Ocean, Autumn,
 * Sakura, Garden and Lavender) and {@link CraftScenes} the other six, each on the {@link Graphics2D} this class hands it.
 * This class holds what they share: the table of colours, the cache and {@link #veil}.
 *
 * <p>Choice: the overlay paints the card every frame, so the last sixteen grounds made are kept, by theme and size, and
 * the same image is handed back for the same key; the image is drawn from and never written to. Sixteen for the reason
 * {@link SpaceSky} gives: the sidebar paints from the cache too, and its few boxes must not be pushed out by the cards at
 * the cursor.
 */
final class SceneSky
{
	/** How many grounds are kept; see the class comment. */
	private static final int KEPT = 16;

	/** What each theme's ground is made of. */
	private static final Map<CardTheme, Look> LOOKS = new EnumMap<>(CardTheme.class);

	/** The grounds kept, the least recently asked for first; guarded by this class's lock. */
	private static final Map<List<Object>, BufferedImage> SKIES = new LinkedHashMap<List<Object>, BufferedImage>(16, 0.75f,
		true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<List<Object>, BufferedImage> eldest)
		{
			return size() > KEPT;
		}
	};

	static
	{
		LOOKS.put(CardTheme.FOREST, new Look(rgb(22, 54, 40), rgb(6, 16, 10), rgb(150, 110, 60)));
		LOOKS.put(CardTheme.OCEAN, new Look(rgb(30, 120, 170), rgb(2, 16, 40), rgb(150, 230, 255)));
		LOOKS.put(CardTheme.AUTUMN, new Look(rgb(150, 70, 26), rgb(34, 14, 8), rgb(230, 140, 50)));
		LOOKS.put(CardTheme.SAKURA, new Look(rgb(40, 22, 64), rgb(16, 8, 22), rgb(255, 196, 224)));
		LOOKS.put(CardTheme.STEAMPUNK, new Look(rgb(70, 46, 28), rgb(34, 20, 10), rgb(200, 150, 70)));
		LOOKS.put(CardTheme.CYBERPUNK, new Look(rgb(28, 8, 46), rgb(6, 2, 12), rgb(255, 60, 210)));
		LOOKS.put(CardTheme.SYNTHWAVE, new Look(rgb(26, 6, 54), rgb(16, 4, 30), rgb(255, 60, 180)));
		LOOKS.put(CardTheme.VOLCANO, new Look(rgb(40, 18, 14), rgb(12, 5, 4), rgb(255, 140, 40)));
		LOOKS.put(CardTheme.RUNIC, new Look(rgb(58, 60, 66), rgb(28, 30, 34), rgb(110, 112, 120)));
		LOOKS.put(CardTheme.SPOOKY, new Look(rgb(46, 22, 60), rgb(10, 6, 14), rgb(255, 140, 40)));
		LOOKS.put(CardTheme.GARDEN, new Look(rgb(70, 110, 70), rgb(22, 40, 24), rgb(240, 236, 220)));
		LOOKS.put(CardTheme.LAVENDER, new Look(rgb(58, 40, 96), rgb(34, 20, 60), rgb(220, 190, 255)));
	}

	private SceneSky()
	{
	}

	/** The colour at the top of {@code theme}'s ground, which is the card style's ground colour. */
	static Color groundTop(CardTheme theme)
	{
		return look(theme).top;
	}

	/** The colour at the bottom of {@code theme}'s ground. */
	static Color groundBottom(CardTheme theme)
	{
		return look(theme).bottom;
	}

	/** The colour of {@code theme}'s edge. */
	static Color edge(CardTheme theme)
	{
		return look(theme).edge;
	}

	/**
	 * The whole ground of {@code theme}, {@code width} by {@code height} px, an opaque ARGB image: the gradient, the
	 * theme's scene and the edge. The same image comes back for the same theme and size, so the caller draws it and never
	 * writes to it. A theme that is not a scene theme is refused.
	 */
	static synchronized BufferedImage of(CardTheme theme, int width, int height)
	{
		final Look look = look(theme);
		final int w = Math.max(1, width);
		final int h = Math.max(1, height);
		final List<Object> key = Arrays.<Object>asList(theme, w, h);
		BufferedImage sky = SKIES.get(key);
		if (sky == null)
		{
			sky = paint(theme, look, w, h);
			SKIES.put(key, sky);
		}
		return sky;
	}

	/**
	 * Lays a black veil over the whole {@code width} by {@code height} image, a gradient from {@code leftAlpha} at its
	 * left edge to {@code rightAlpha} at its right edge (0 to 255 each), so that words over a scene stay easy to read.
	 */
	static void veil(Graphics2D g, int width, int height, int leftAlpha, int rightAlpha)
	{
		g.setPaint(new GradientPaint(0f, 0f, new Color(0, 0, 0, leftAlpha), Math.max(1, width - 1), 0f,
			new Color(0, 0, 0, rightAlpha)));
		g.fillRect(0, 0, width, height);
	}

	private static Look look(CardTheme theme)
	{
		final Look look = theme == null ? null : LOOKS.get(theme);
		if (look == null)
		{
			throw new IllegalArgumentException("not a scene theme: " + theme);
		}
		return look;
	}

	private static BufferedImage paint(CardTheme theme, Look look, int w, int h)
	{
		final BufferedImage image = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			if (nature(theme))
			{
				NatureScenes.paint(theme, g, w, h);
			}
			else
			{
				CraftScenes.paint(theme, g, w, h);
			}
		}
		finally
		{
			g.dispose();
		}
		return image;
	}

	/** Whether {@code theme} is one of the six {@link NatureScenes} paints; the other six are {@link CraftScenes}'. */
	private static boolean nature(CardTheme theme)
	{
		return theme == CardTheme.FOREST || theme == CardTheme.OCEAN || theme == CardTheme.AUTUMN
			|| theme == CardTheme.SAKURA || theme == CardTheme.GARDEN || theme == CardTheme.LAVENDER;
	}

	private static Color rgb(int red, int green, int blue)
	{
		return new Color(red, green, blue);
	}

	/** What a theme's ground is made of: its colour at the top and at the bottom, and its edge. */
	private static final class Look
	{
		final Color top;
		final Color bottom;
		final Color edge;

		Look(Color top, Color bottom, Color edge)
		{
			this.top = top;
			this.bottom = bottom;
			this.edge = edge;
		}
	}
}

package com.clanhub;

import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;

/**
 * Where a window goes on the screen, worked out apart from any window so that it can be tested: nothing here touches
 * the screen itself, the caller hands over the room it has.
 */
final class ScreenPlace
{
	/** The gap between a window's right edge and the point it opens beside. */
	static final int LEFT_GAP = 8;

	/** How far above the point a window's top edge sits, so that the point is near the window's title. */
	static final int RAISE = 20;

	private ScreenPlace()
	{
	}

	/**
	 * The top-left corner for a window of {@code size} that opens to the left of {@code at}: its right edge
	 * {@link #LEFT_GAP} px left of {@code at.x} and its top {@link #RAISE} px above {@code at.y}, held inside
	 * {@code screen} (at its left and top edges when the window is bigger than the room).
	 *
	 * @param at the point on the screen the window opens beside, the centre of a swatch just pressed
	 * @param size the window's size
	 * @param screen the usable area of the screen the point is on
	 */
	static Point leftOf(Point at, Dimension size, Rectangle screen)
	{
		final int x = at.x - LEFT_GAP - size.width;
		final int y = at.y - RAISE;
		return new Point(
			Math.max(screen.x, Math.min(x, screen.x + screen.width - size.width)),
			Math.max(screen.y, Math.min(y, screen.y + screen.height - size.height)));
	}
}

package com.clanhub;

import com.clanhub.ClanHubConfig.CardTheme;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Paint;
import java.awt.RadialGradientPaint;
import java.awt.geom.Point2D;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import net.runelite.client.ui.ColorScheme;

/**
 * What the sidebar paints with: the colours of its ground, its titles, its words and its rows, and the look of its three
 * boxes (the top card, the how-to's bar and a recent card's row). Pure: a theme in, a skin out, and the painting of a
 * box on a {@link Graphics2D} handed in; {@link ClanHubPanel} draws the sidebar's content in these colours.
 *
 * <p>{@link #PLAIN} is the sidebar as it always was (RuneLite's own greys, flat boxes), which Classic gives. Stone, Void
 * and Wiki dress the boxes as their cards are dressed (Stone's frame, Void's gradient and stars, Wiki's beige and thin
 * brown edge); each of the eight space themes and the twelve scene themes paints a calm version of its sky (the
 * ground's gradient, a soft corner glow, the edge) into the top card and the rows, and its top colour into the bar. The words carry no shadow and no glow
 * (they are Swing labels), so the colours are the whole of a skin's words.
 */
final class SidebarSkin
{
	/** How strong the calm sky boxes' corner glow is at its brightest. */
	private static final int CALM_GLOW_ALPHA = 60;

	/** The three boxes the sidebar paints: the top card, the how-to's title bar and a recent card's row. */
	enum Box
	{
		CARD,
		BAR,
		ROW
	}

	/** How a skin paints a box of {@code width} by {@code height} px at the graphics' origin. */
	private interface Painter
	{
		void paint(Graphics2D g, int width, int height, Box kind);
	}

	/** The Stone row's and bar's own colours, from the sidebar mock-up. */
	private static final Color STONE_ROW_LINE = new Color(110, 98, 80);
	private static final Color STONE_BAR = new Color(45, 39, 31);
	private static final Color STONE_BAR_EDGE = new Color(30, 26, 20);
	private static final Color STONE_BAR_LINE = new Color(100, 90, 72);

	/** The Void bar's gradient, top and bottom, and its edge. */
	private static final Color VOID_BAR_TOP = new Color(72, 34, 112);
	private static final Color VOID_BAR_BOTTOM = new Color(46, 20, 74);
	private static final Color VOID_BAR_EDGE = new Color(176, 118, 246);

	/** The Wiki boxes: the card, the row and the bar, and the edge of each. */
	private static final Color WIKI_CARD = new Color(234, 226, 210);
	private static final Color WIKI_CARD_EDGE = new Color(150, 135, 105);
	private static final Color WIKI_ROW = new Color(244, 238, 226);
	private static final Color WIKI_ROW_EDGE = new Color(180, 165, 135);
	private static final Color WIKI_BAR = new Color(194, 172, 136);

	/** What lies over a box under the mouse: a light veil on a dark skin, a dark one on Wiki's light ground. */
	private static final Color LIGHT_VEIL = new Color(255, 255, 255, 26);
	private static final Color DARK_VEIL = new Color(0, 0, 0, 24);

	/** The sidebar as it always was: RuneLite's own greys, flat boxes, and a lighter grey under the mouse. */
	static final SidebarSkin PLAIN = new SidebarSkin(ColorScheme.DARKER_GRAY_COLOR, Color.WHITE, Color.WHITE,
		ColorScheme.LIGHT_GRAY_COLOR, ClanHubPanel.HOW_TO_HEADING_COLOUR, null, ClanHubPanel.ROW_TIME_COLOUR,
		ColorScheme.DARK_GRAY_HOVER_COLOR, (g, width, height, kind) ->
		{
			g.setColor(kind == Box.BAR ? ClanHubPanel.HOW_TO_BAR_COLOUR : ColorScheme.DARK_GRAY_COLOR);
			g.fillRect(0, 0, width, height);
		});

	/** The twelve scene themes, Forest to Lavender; the other themes after Wiki are the space themes. */
	private static final Set<CardTheme> SCENES = EnumSet.range(CardTheme.FOREST, CardTheme.LAVENDER);

	/** Every theme's skin, by theme. */
	private static final Map<CardTheme, SidebarSkin> SKINS = new EnumMap<>(CardTheme.class);

	static
	{
		SKINS.put(CardTheme.STONE, new SidebarSkin(new Color(36, 31, 25), new Color(255, 152, 31), Color.WHITE,
			new Color(205, 188, 150), new Color(175, 160, 128), null, new Color(175, 160, 128), LIGHT_VEIL,
			SidebarSkin::stone));
		SKINS.put(CardTheme.VOID, new SidebarSkin(new Color(12, 6, 26), new Color(228, 194, 255), new Color(236, 226, 250),
			new Color(162, 142, 202), new Color(142, 122, 182), null, new Color(142, 122, 182), LIGHT_VEIL,
			SidebarSkin::voidLook));
		SKINS.put(CardTheme.WIKI, new SidebarSkin(new Color(222, 213, 193), new Color(38, 28, 16), new Color(30, 25, 15),
			new Color(110, 95, 70), new Color(120, 105, 80), new Color(42, 92, 172), new Color(120, 105, 80), DARK_VEIL,
			SidebarSkin::wiki));
		for (final CardTheme theme : CardTheme.values())
		{
			if (theme != CardTheme.CLASSIC && !SKINS.containsKey(theme))
			{
				final CardStyle style = CardStyle.of(theme);
				final boolean scene = SCENES.contains(theme);
				final Color page = scene ? SceneSky.groundBottom(theme) : SpaceSky.groundBottom(theme);
				SKINS.put(theme, new SidebarSkin(page, style.title, style.text, style.label, style.hint, null, style.hint,
					LIGHT_VEIL, (g, width, height, kind) -> sky(g, theme, scene, width, height, kind)));
			}
		}
	}

	/** The panel's own ground, behind the boxes, the list and the scroll pane. */
	final Color page;
	/** The words of the how-to bar and of the recent cards' header. */
	final Color title;
	/** The action line, the how-to's labels, and a row's title unless the skin sets {@link #rowTitle}. */
	final Color text;
	/** The how-to's second line and rest-of-row words, and the rows' kind, the count and the clear link. */
	final Color grey;
	/** The how-to's small heading. */
	final Color heading;
	/** A row's title: the skin's own colour for it, or {@link #text} when the skin sets none. */
	final Color rowTitle;
	/** A row's time. */
	final Color time;
	/** What is laid over a bar or a row while the mouse is on it. */
	final Color hot;
	private final Painter painter;

	private SidebarSkin(Color page, Color title, Color text, Color grey, Color heading, Color rowTitle, Color time,
		Color hot, Painter painter)
	{
		this.page = page;
		this.title = title;
		this.text = text;
		this.grey = grey;
		this.heading = heading;
		this.rowTitle = rowTitle == null ? text : rowTitle;
		this.time = time;
		this.hot = hot;
		this.painter = painter;
	}

	/** The skin of {@code theme}; Classic, and a null theme, give {@link #PLAIN}. */
	static SidebarSkin of(CardTheme theme)
	{
		final SidebarSkin skin = theme == null ? null : SKINS.get(theme);
		return skin == null ? PLAIN : skin;
	}

	/**
	 * Paints a box of {@code width} by {@code height} px with its top-left corner at the graphics' origin: the top card
	 * and a row as the card theme paints its card (a row of Stone without the band and the rivets), the bar in a shade of
	 * its own. The box's whole area is painted.
	 */
	void paintBox(Graphics2D g, int width, int height, Box kind)
	{
		painter.paint(g, width, height, kind);
	}

	/** Stone: the card is the card's frame, a row is its ground and speckle with the black edge and the light line alone. */
	private static void stone(Graphics2D g, int width, int height, Box kind)
	{
		if (kind == Box.CARD)
		{
			CardStyle.STONE.frame(g, 0, 0, width, height);
		}
		else if (kind == Box.ROW)
		{
			g.setColor(CardStyle.STONE.ground);
			g.fillRect(0, 0, width, height);
			CardStyle.STONE.lay(g, 0, 0, width, height);
			g.setColor(Color.BLACK);
			g.drawRect(0, 0, width - 1, height - 1);
			g.setColor(STONE_ROW_LINE);
			g.drawRect(1, 1, width - 3, height - 3);
		}
		else
		{
			g.setColor(STONE_BAR);
			g.fillRect(0, 0, width, height);
			g.setColor(STONE_BAR_EDGE);
			g.drawRect(0, 0, width - 1, height - 1);
			g.setColor(STONE_BAR_LINE);
			g.fillRect(0, height - 1, width, 1);
		}
	}

	/** Void: the card and a row are the card's frame, the bar a lighter purple gradient with a light purple edge. */
	private static void voidLook(Graphics2D g, int width, int height, Box kind)
	{
		if (kind == Box.BAR)
		{
			g.setPaint(new GradientPaint(0, 0, VOID_BAR_TOP, 0, height, VOID_BAR_BOTTOM));
			g.fillRect(0, 0, width, height);
			g.setColor(VOID_BAR_EDGE);
			g.drawRect(0, 0, width - 1, height - 1);
		}
		else
		{
			CardStyle.VOID.frame(g, 0, 0, width, height);
		}
	}

	/** Wiki: beige boxes with a thin brown edge, a row lighter than the card, the bar darker. */
	private static void wiki(Graphics2D g, int width, int height, Box kind)
	{
		final Color fill = kind == Box.BAR ? WIKI_BAR : kind == Box.ROW ? WIKI_ROW : WIKI_CARD;
		final Color edge = kind == Box.ROW ? WIKI_ROW_EDGE : WIKI_CARD_EDGE;
		g.setColor(fill);
		g.fillRect(0, 0, width, height);
		g.setColor(edge);
		g.drawRect(0, 0, width - 1, height - 1);
	}

	/**
	 * A space or scene theme: the card and a row are a calm version of its sky, its ground's gradient with a soft glow of
	 * its title's glow colour in the top right corner and its edge colour round it; the bar is its ground's top colour
	 * with the edge round it.
	 *
	 * <p>Choice: the sky's own picture (a planet, a fence, gears, a black hole) is left out of the sidebar's boxes. It was
	 * drawn into them at first, and in a row 40 px tall it sat behind the title and the name and made them hard to read
	 * (the user's look at the renders, 2026-10-26); the card at the chat keeps it.
	 */
	private static void sky(Graphics2D g, CardTheme theme, boolean scene, int width, int height, Box kind)
	{
		final Color top = scene ? SceneSky.groundTop(theme) : SpaceSky.ground(theme);
		final Color edge = scene ? SceneSky.edge(theme) : SpaceSky.edge(theme);
		if (kind == Box.BAR)
		{
			g.setColor(top);
			g.fillRect(0, 0, width, height);
			g.setColor(edge);
			g.drawRect(0, 0, width - 1, height - 1);
			return;
		}
		final Color bottom = scene ? SceneSky.groundBottom(theme) : SpaceSky.groundBottom(theme);
		final Paint before = g.getPaint();
		g.setPaint(new GradientPaint(0, 0, top, 0, Math.max(1, height), bottom));
		g.fillRect(0, 0, width, height);
		final Color glow = CardStyle.of(theme).titleGlow;
		if (glow != null && width > 2 && height > 2)
		{
			final Color from = new Color(glow.getRed(), glow.getGreen(), glow.getBlue(), CALM_GLOW_ALPHA);
			final Color to = new Color(glow.getRed(), glow.getGreen(), glow.getBlue(), 0);
			g.setPaint(new RadialGradientPaint(new Point2D.Float(width, 0), Math.max(width, height) * 0.6f,
				new float[] {0f, 1f}, new Color[] {from, to}));
			g.fillRect(0, 0, width, height);
		}
		g.setPaint(before);
		g.setColor(edge);
		g.drawRect(0, 0, width - 1, height - 1);
	}
}

