package com.clanhub;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.List;

/**
 * Lays a card out as the wiki's own infobox, the look of the Wiki theme. Pure drawing: a {@link HoverCard}, a picture,
 * a size, a width and the description text in, pixels and the card's size out. {@link CardPainter} hands a card to it
 * when the card's {@link CardStyle} is an infobox; the colours that the style names are the style's, the rest of the
 * infobox's (the bar, the cells, the link blue) are this class's.
 *
 * <p>From the top: the title in a bar across the card, centred, with the stack after it; the picture in a cell at the
 * left with the facts as a two-column table beside it, one row to a fact; for an item, the drops as a table of the
 * source (in link blue) and its rate; the description (a paragraph, or the numbered list) across the card; and the hint,
 * its "Open wiki" a link. It is exactly as wide as it is asked, whatever it holds. The type is Java's own sans serif,
 * the wiki's own look, not the game's. Every size is given at 16 px and grows and shrinks with the text size.
 */
final class WikiCard
{
	/** The title bar, and the header row of the drops. */
	private static final Color BAR = new Color(194, 172, 136);
	/** The stack after the title. */
	private static final Color STACK = new Color(90, 75, 55);
	/** The picture's cell, a fact's value cell and every other row of the drops. */
	private static final Color CELL = new Color(244, 238, 226);
	/** A fact's label cell. */
	private static final Color LABEL_CELL = new Color(214, 202, 178);
	/** The edge of a drop's row. */
	private static final Color DROP_EDGE = new Color(205, 192, 165);
	/** A source, and the hint's "Open wiki". */
	private static final Color LINK = new Color(42, 92, 172);

	/** The air above and below the title in its bar, in px (at 16 px). */
	private static final int BAR_AIR = 4;
	/** The gap under the bar and between the picture's cell and the facts, in px. */
	private static final int GAP = 6;
	/** The gap above the drops and above the description, in px. */
	private static final int SECTION_GAP = 8;
	/** The gap above the hint, in px. */
	private static final int HINT_GAP = 6;
	/** What a fact row and the drops' header row are taller than a line of text, and a drop's row, in px. */
	private static final int ROW_PAD = 6;
	private static final int DROP_PAD = 5;
	/** The air at each side of a cell's text, and a column's extra width over its widest text, in px. */
	private static final int CELL_AIR = 6;
	private static final int COLUMN_PAD = 12;
	/** The picture's cell is this wide, in px: a card with the wiki's picture has the bigger one. */
	private static final int PICTURE_CELL = 52;
	private static final int PICTURE_CELL_BIG = 72;

	/** The words of the hint that are a link. */
	private static final String LINK_WORDS = "Open wiki";
	/** The drops' column heads. */
	private static final String SOURCE = "Source";
	private static final String RARITY = "Rarity";

	private WikiCard()
	{
	}

	/**
	 * Paints the infobox with its top-left corner at ({@code x}, {@code y}), exactly {@code width} px wide, and returns
	 * its size. The title bar, the picture and the facts, the drops, the {@code description} ("" for none: a paragraph,
	 * or a numbered list when it holds line breaks, see {@link CardPainter#layout}, in at most {@code maxLines} lines, a
	 * list taking its own cap) and the hint, in that order; the ground and the one pixel edge are the Wiki style's. The
	 * title is cut with "..." where it would not fit the bar, a source where it would pass its column. The text is
	 * antialiased.
	 *
	 * <p>Choice: the measuring pass and the drawing pass are one layout, run twice: the first draws nothing and gives the
	 * height the ground and the edge need, the second draws.
	 */
	static Dimension paint(Graphics2D g, HoverCard card, BufferedImage picture, int fontSize, int x, int y,
		String description, int width, int maxLines)
	{
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		final Sheet sheet = new Sheet(g, card, picture, fontSize, width, description, maxLines);
		final int height = sheet.lay(false, x, y);
		CardStyle.WIKI.frame(g, x, y, width, height);
		sheet.lay(true, x, y);
		return new Dimension(width, height);
	}

	/** A sans serif font whose size, given at 16 px, is scaled to {@code fontSize}. */
	private static Font sans(int style, int sizeAt16, int fontSize)
	{
		return new Font(Font.SANS_SERIF, style, Math.max(1, Math.round(sizeAt16 * fontSize / 16f)));
	}

	/** What one infobox is laid out and drawn with: its fonts and metrics, its parts, and the pen. */
	private static final class Sheet
	{
		private final Graphics2D g;
		private final BufferedImage picture;
		private final int fontSize;
		private final int width;
		private final CardStyle style = CardStyle.WIKI;
		private final String name;
		private final String stack;
		private final String hint;
		private final boolean widePicture;
		private final List<HoverCard.Pair> facts;
		private final List<HoverCard.Pair> drops;
		private final List<CardPainter.TextLine> lines;
		private final Font title;
		private final Font bold;
		private final Font plain;
		private final Font text;
		private final Font small;
		private final FontMetrics titleMetrics;
		private final FontMetrics boldMetrics;
		private final FontMetrics plainMetrics;
		private final FontMetrics textMetrics;
		private final FontMetrics smallMetrics;
		/** The card's content width, between the insets, in px. */
		private final int inner;
		/** A line of the table font, ascent and descent; of the paragraph font and of the hint, with 2 more. */
		private final int tableLine;
		private final int textLine;
		private final int hintLine;
		private boolean draw;

		Sheet(Graphics2D g, HoverCard card, BufferedImage picture, int fontSize, int width, String description,
			int maxLines)
		{
			this.g = g;
			this.picture = picture;
			this.fontSize = fontSize;
			this.width = width;
			this.inner = Math.max(1, width - 2 * style.inset);
			this.name = CardPainter.nameOf(card);
			final String quantity = CardPainter.stackOf(card);
			this.stack = quantity == null ? "" : " " + quantity;
			this.hint = card.hint();
			this.widePicture = card.wikiPicture();
			this.facts = CardPainter.factsOf(card);
			this.drops = CardPainter.dropsOf(card);
			this.title = sans(Font.BOLD, 15, fontSize);
			this.bold = sans(Font.BOLD, 13, fontSize);
			this.plain = sans(Font.PLAIN, 13, fontSize);
			this.text = sans(Font.PLAIN, 14, fontSize);
			this.small = sans(Font.PLAIN, 12, fontSize);
			this.titleMetrics = g.getFontMetrics(title);
			this.boldMetrics = g.getFontMetrics(bold);
			this.plainMetrics = g.getFontMetrics(plain);
			this.textMetrics = g.getFontMetrics(text);
			this.smallMetrics = g.getFontMetrics(small);
			this.tableLine = plainMetrics.getAscent() + plainMetrics.getDescent();
			this.textLine = textMetrics.getAscent() + textMetrics.getDescent() + 2;
			this.hintLine = smallMetrics.getAscent() + smallMetrics.getDescent() + 2;
			this.lines = CardPainter.layout(description, textMetrics, inner, maxLines);
		}

		/** A size given at 16 px, at this card's text size. */
		private int sc(int atBase)
		{
			return CardPainter.scaled(atBase, fontSize);
		}

		/**
		 * Lays the card out from its top-left corner ({@code x}, {@code y}), drawing it when {@code drawing}; returns the
		 * card's height, the inset under the hint included.
		 */
		int lay(boolean drawing, int x, int y)
		{
			this.draw = drawing;
			final int left = x + style.inset;
			// The last pixel column a table's border is drawn on: as far from the card's edge as the first is.
			final int right = left + inner - 1;

			// The title bar, across the card inside the edge.
			final int barHeight = titleMetrics.getAscent() + titleMetrics.getDescent() + 2 * sc(BAR_AIR);
			int cursor = y + 1;
			fill(x + 1, cursor, width - 2, barHeight, BAR);
			final int stackWidth = stack.isEmpty() ? 0 : titleMetrics.stringWidth(stack);
			final String shown = CardPainter.fit(name, titleMetrics, Math.max(1, inner - stackWidth));
			final int titleLeft = x + (width - titleMetrics.stringWidth(shown) - stackWidth) / 2;
			final int titleBaseline = cursor + sc(BAR_AIR) + titleMetrics.getAscent();
			string(shown, title, style.title, titleLeft, titleBaseline);
			string(stack, title, STACK, titleLeft + titleMetrics.stringWidth(shown), titleBaseline);
			cursor += barHeight + sc(GAP);

			cursor += pictureAndFacts(left, right, cursor);
			if (!drops.isEmpty())
			{
				cursor += sc(SECTION_GAP);
				cursor += dropTable(left, right, cursor);
			}
			if (!lines.isEmpty())
			{
				cursor += sc(SECTION_GAP);
				for (final CardPainter.TextLine line : lines)
				{
					string(line.text, text, style.text, left + line.indent, cursor + textMetrics.getAscent());
					cursor += textLine;
				}
			}
			cursor += sc(HINT_GAP);
			drawHint(left, cursor + smallMetrics.getAscent());
			cursor += hintLine;
			return cursor + style.inset - y;
		}

		/**
		 * The picture's cell at the left and the facts as a table beside it, from ({@code left}, {@code top}); returns
		 * the block's height: the facts' rows, or the cell's own width when that is more. A card with no facts has the
		 * cell alone.
		 */
		private int pictureAndFacts(int left, int right, int top)
		{
			final int cellWidth = sc(widePicture ? PICTURE_CELL_BIG : PICTURE_CELL);
			final int rowHeight = tableLine + sc(ROW_PAD);
			final int height = Math.max(facts.size() * rowHeight, cellWidth);
			cell(left, top, cellWidth, height, CELL, style.rule);
			fitted(left + 1, top + 1, cellWidth - 1, height - 1);
			if (facts.isEmpty())
			{
				return height;
			}

			final int tableLeft = left + cellWidth + sc(GAP);
			int labelWidth = 0;
			for (final HoverCard.Pair fact : facts)
			{
				labelWidth = Math.max(labelWidth, boldMetrics.stringWidth(fact.label));
			}
			labelWidth = Math.min(labelWidth + sc(COLUMN_PAD), Math.max(1, (right - tableLeft) / 2));
			final int air = sc(CELL_AIR);
			for (int k = 0; k < facts.size(); k++)
			{
				final HoverCard.Pair fact = facts.get(k);
				final int rowTop = top + k * rowHeight;
				final int baseline = rowTop + (rowHeight - tableLine) / 2 + plainMetrics.getAscent();
				cell(tableLeft, rowTop, labelWidth, rowHeight, LABEL_CELL, style.rule);
				cell(tableLeft + labelWidth, rowTop, right - tableLeft - labelWidth, rowHeight, CELL, style.rule);
				string(CardPainter.fit(fact.label, boldMetrics, Math.max(1, labelWidth - air)), bold, style.label,
					tableLeft + air, baseline);

				final int valueLeft = tableLeft + labelWidth + air;
				final int room = Math.max(1, right - valueLeft - air);
				final String value = CardPainter.fit(fact.value, plainMetrics, room);
				string(value, plain, style.value, valueLeft, baseline);
				final int used = plainMetrics.stringWidth(value);
				if (value.equals(fact.value) && !fact.note.isEmpty())
				{
					final String note = CardPainter.fit(fact.note, plainMetrics, Math.max(1, room - used));
					if (used + plainMetrics.stringWidth(note) <= room)
					{
						string(note, plain, style.hint, valueLeft + used, baseline);
					}
				}
			}
			return height;
		}

		/**
		 * The drops as a table across the card, from ({@code left}, {@code top}): a header row, then a row to a drop, the
		 * source at the left in link blue and the rate in a column of its own at the right; returns the table's height.
		 */
		private int dropTable(int left, int right, int top)
		{
			int rateWidth = boldMetrics.stringWidth(RARITY);
			for (final HoverCard.Pair drop : drops)
			{
				rateWidth = Math.max(rateWidth, plainMetrics.stringWidth(drop.value));
			}
			rateWidth += sc(COLUMN_PAD);
			final int air = sc(CELL_AIR);
			final int rateLeft = left + inner - rateWidth;
			final int headHeight = tableLine + sc(ROW_PAD);
			final int rowHeight = tableLine + sc(DROP_PAD);

			cell(left, top, right - left, headHeight, BAR, style.rule);
			final int headBaseline = top + (headHeight - tableLine) / 2 + boldMetrics.getAscent();
			string(SOURCE, bold, style.title, left + air, headBaseline);
			string(RARITY, bold, style.title, rateLeft + air, headBaseline);

			int rowTop = top + headHeight;
			for (int i = 0; i < drops.size(); i++)
			{
				final HoverCard.Pair drop = drops.get(i);
				cell(left, rowTop, right - left, rowHeight, i % 2 == 0 ? CELL : style.ground, DROP_EDGE);
				final int baseline = rowTop + (rowHeight - tableLine) / 2 + plainMetrics.getAscent();
				if (drop.value.isEmpty())
				{
					string(CardPainter.fit(drop.label, plainMetrics, Math.max(1, inner - 2 * air)), plain, LINK,
						left + air, baseline);
				}
				else
				{
					string(CardPainter.fit(drop.label, plainMetrics, Math.max(1, rateLeft - left - 2 * air)), plain, LINK,
						left + air, baseline);
					string(drop.value, plain, style.value, rateLeft + air, baseline);
				}
				rowTop += rowHeight;
			}
			return rowTop - top;
		}

		/** The hint on {@code baseline}, its "Open wiki" in link blue with a line under it. */
		private void drawHint(int left, int baseline)
		{
			final int at = hint.indexOf(LINK_WORDS);
			if (at < 0)
			{
				string(hint, small, style.hint, left, baseline);
				return;
			}
			final String before = hint.substring(0, at);
			final String after = hint.substring(at + LINK_WORDS.length());
			final int linkLeft = left + smallMetrics.stringWidth(before);
			final int linkWidth = smallMetrics.stringWidth(LINK_WORDS);
			string(before, small, style.hint, left, baseline);
			string(LINK_WORDS, small, LINK, linkLeft, baseline);
			fill(linkLeft, baseline + 2, linkWidth, 1, LINK);
			string(after, small, style.hint, linkLeft + linkWidth, baseline);
		}

		/** A cell: {@code fill} over the rectangle and a 1 px {@code edge} round it, the edge on the last column and row too. */
		private void cell(int x, int y, int w, int h, Color fill, Color edge)
		{
			if (draw)
			{
				g.setColor(fill);
				g.fillRect(x, y, w + 1, h + 1);
				g.setColor(edge);
				g.drawRect(x, y, w, h);
			}
		}

		private void fill(int x, int y, int w, int h, Color colour)
		{
			if (draw)
			{
				g.setColor(colour);
				g.fillRect(x, y, w, h);
			}
		}

		private void string(String words, Font font, Color colour, int x, int baseline)
		{
			if (draw && !words.isEmpty())
			{
				g.setFont(font);
				g.setColor(colour);
				g.drawString(words, x, baseline);
			}
		}

		/**
		 * Draws the picture centred, both ways, in the {@code w} by {@code h} rectangle at ({@code x}, {@code y}); a
		 * picture wider or taller than it is drawn scaled down to fit, its ratio kept. A null picture leaves it empty.
		 */
		private void fitted(int x, int y, int w, int h)
		{
			if (!draw || picture == null)
			{
				return;
			}
			final int pictureWidth = picture.getWidth();
			final int pictureHeight = picture.getHeight();
			if (pictureWidth <= w && pictureHeight <= h)
			{
				g.drawImage(picture, x + (w - pictureWidth) / 2, y + (h - pictureHeight) / 2, null);
				return;
			}
			final double scale = Math.min(w / (double) pictureWidth, h / (double) pictureHeight);
			final int fittedWidth = Math.max(1, (int) Math.round(pictureWidth * scale));
			final int fittedHeight = Math.max(1, (int) Math.round(pictureHeight * scale));
			g.drawImage(picture, x + (w - fittedWidth) / 2, y + (h - fittedHeight) / 2, fittedWidth, fittedHeight, null);
		}
	}
}

package com.clanhub;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.Image;
import java.awt.MediaTracker;
import java.awt.Toolkit;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.swing.ImageIcon;
import net.runelite.client.util.ImageUtil;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The wiki's own picture of a page, for the cards of a boss, monster, raid or chest to show in their big picture box: the
 * Old School RuneScape Wiki is asked for the page's lead image when a chat line with such a card arrives, the picture is
 * kept, and the card reads it from here when it is hovered. It is the twin of {@link WikiSummaries}: the same host, the
 * same User-Agent, the same RuneLite HTTP client asked in the background ({@code enqueue}, never {@code execute}), the
 * same caps. What is sent is the page's title and nothing else; the answer names the picture's own address, which is
 * followed only when it is on {@code oldschool.runescape.wiki} and a PNG, GIF or JPEG (the wiki's WebP files cannot be
 * shown by the client, so they are never fetched). The picture is decoded with the AWT toolkit's own decoder and
 * scaled down to fit a {@value #BOX} px square, its longer side {@value #BOX} and nothing cropped, on the HTTP client's
 * thread, never the client thread; a picture already that small is kept as it is. A title is asked for once: a page that
 * failed, or has no picture, is remembered as having none and not asked again. When the wiki says there is no page of
 * that title, its own search is asked once for the name and the first hit's picture is used instead, as the
 * summaries do for the paragraph, but only when the hit's title shares a word with the name
 * ({@link WikiSummaries#nearEnough}); otherwise the card keeps its icon. The asking is capped (10 titles at a time, 60
 * calls a minute, each page, search and picture call counting, 1 MB read of a picture), and the pictures kept are the
 * 200 asked for last.
 *
 * <p>Choice: a failed call is never retried in the same run; one warning is logged the first time a call fails, and the
 * later ones go to the debug log, so a wiki that is down does not fill the log.
 */
final class WikiPictures
{
	private static final Logger log = LoggerFactory.getLogger(WikiPictures.class);

	/** The width the wiki is asked to scale its picture to, in px. */
	private static final int THUMB = 128;
	/** The side of the square box a kept picture is fitted to, in px. */
	private static final int BOX = 64;
	/** How many pictures are kept; the oldest go first. */
	private static final int MAX_CACHED = 200;
	/** How many titles may be waiting for an answer at once. */
	private static final int MAX_IN_FLIGHT = 10;
	/** How many calls may be started in one minute. */
	private static final int MAX_PER_MINUTE = 60;
	/** A minute, in {@link System#nanoTime} terms. */
	private static final long MINUTE_NANOS = 60_000_000_000L;
	/** The most bytes of a picture that are read; a longer one is dropped. */
	private static final long MAX_BYTES = 1_000_000L;

	private final Call.Factory calls;
	private final Gson gson;
	/** Guards everything below: the answers arrive on the HTTP client's thread and are read on the client thread. */
	private final Object lock = new Object();
	/**
	 * The fitted pictures by title, null for a page that failed or has none; at most {@link #MAX_CACHED}, the oldest out.
	 * A title that is a key was asked for, whatever its value.
	 */
	private final Map<String, BufferedImage> cache = new LinkedHashMap<String, BufferedImage>()
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, BufferedImage> eldest)
		{
			return size() > MAX_CACHED;
		}
	};
	/** The titles whose chain of calls (page, search, nearest page, picture) has not ended yet. */
	private final Set<String> inFlight = new HashSet<>();
	/** When the current minute began, in {@link System#nanoTime} terms, and how many calls it has started. */
	private long windowStart = System.nanoTime();
	private int startedInWindow;
	/** Whether a failed call has been logged as a warning yet. */
	private boolean warned;

	/**
	 * @param calls where calls are made: RuneLite's own HTTP client (an {@code okhttp3.Call.Factory}), or a stand-in in a test
	 * @param gson RuneLite's Gson, which reads the answer
	 */
	WikiPictures(Call.Factory calls, Gson gson)
	{
		this.calls = calls;
		this.gson = gson;
	}

	/**
	 * The request for a page's lead image: the wiki's {@code api.php} asked for the page's thumbnail, 128 px wide, redirects
	 * followed, as JSON; the title is percent-encoded (a space as %20). It carries this plugin's User-Agent and nothing
	 * about the player.
	 */
	static Request requestFor(String title)
	{
		final HttpUrl url = new HttpUrl.Builder()
			.scheme("https")
			.host(WikiSummaries.HOST)
			.addPathSegments("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("prop", "pageimages")
			.addQueryParameter("piprop", "thumbnail")
			.addQueryParameter("pithumbsize", String.valueOf(THUMB))
			.addQueryParameter("redirects", "1")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("titles", title)
			.build();
		return new Request.Builder().url(url).header("User-Agent", WikiSummaries.USER_AGENT).build();
	}

	/** The request for the picture at {@code url}, which {@link #thumbnailUrl} has checked: a GET with the User-Agent. */
	static Request requestForPicture(HttpUrl url)
	{
		return new Request.Builder().url(url).header("User-Agent", WikiSummaries.USER_AGENT).build();
	}

	/**
	 * The address of the thumbnail the wiki's page answer holds: the first page's {@code thumbnail.source}. The answer is
	 * {@code {"query": {"pages": [{"title": "...", "thumbnail": {"source": "https://...", ...}}]}}}. Null unless the address
	 * is on {@code https}, on the wiki's own host, and its last path segment, in lower case, ends in {@code .png},
	 * {@code .gif}, {@code .jpg} or {@code .jpeg}; null as well for a page that is missing or has no thumbnail, an answer
	 * with no pages, an empty answer, or text that is not JSON.
	 */
	static HttpUrl thumbnailUrl(String json, Gson gson)
	{
		final JsonObject page = WikiSummaries.firstPage(json, gson);
		final JsonElement thumbnail = page == null ? null : page.get("thumbnail");
		if (thumbnail == null || !thumbnail.isJsonObject())
		{
			return null;
		}
		final JsonElement source = thumbnail.getAsJsonObject().get("source");
		if (source == null || !source.isJsonPrimitive())
		{
			return null;
		}
		final HttpUrl url = HttpUrl.parse(source.getAsString());
		if (url == null || !"https".equals(url.scheme()) || !WikiSummaries.HOST.equals(url.host()))
		{
			return null;
		}
		final String file = url.pathSegments().get(url.pathSegments().size() - 1).toLowerCase(Locale.ROOT);
		return file.endsWith(".png") || file.endsWith(".gif") || file.endsWith(".jpg") || file.endsWith(".jpeg") ? url : null;
	}

	/**
	 * The picture the bytes hold, as an ARGB image with its transparency kept, decoded by the AWT toolkit and loaded
	 * through an icon so that it is complete when this returns; null for null or empty bytes, for bytes the toolkit cannot
	 * read (a WebP file, a page of text), and for a picture with no size.
	 */
	static BufferedImage decode(byte[] bytes)
	{
		if (bytes == null || bytes.length == 0)
		{
			return null;
		}
		try
		{
			final Image image = Toolkit.getDefaultToolkit().createImage(bytes);
			final ImageIcon icon = new ImageIcon(image);
			if (icon.getImageLoadStatus() != MediaTracker.COMPLETE || icon.getIconWidth() <= 0 || icon.getIconHeight() <= 0)
			{
				return null;
			}
			return ImageUtil.bufferedImageFromImage(icon.getImage());
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * The picture as the cards keep it: the picture itself when both its sides are {@value #BOX} px or less, else scaled
	 * down so that its longer side is {@value #BOX} and the other follows the ratio. Never scaled up, never cropped.
	 */
	static BufferedImage fit(BufferedImage picture)
	{
		if (picture.getWidth() <= BOX && picture.getHeight() <= BOX)
		{
			return picture;
		}
		return ImageUtil.resizeImage(picture, BOX, BOX, true);
	}

	/**
	 * The picture kept for a title, fitted to the box, or null when the title was never asked for, its answer has not come
	 * yet, or the page has none (or none that could be read).
	 */
	BufferedImage pictureOf(String title)
	{
		synchronized (lock)
		{
			return cache.get(title);
		}
	}

	/**
	 * Asks the wiki for a title's picture in the background. Nothing happens when the title is blank, already asked for,
	 * already waiting for its answer, when 10 titles are already waiting, or when 60 calls have been started in the last
	 * minute (the title is then asked for again by the next hover). The page is asked first; a page with no picture the
	 * client can show ends the chain with none, and a page with one leads to a second call for the picture's own address,
	 * whose body is read up to 1 MB, decoded, fitted and kept. A picture that is too long, cannot be read, or whose call
	 * failed is kept as none. Each of the two calls counts in the minute; when the minute is full before the second, the
	 * title is let go unkept and the next hover asks again. A page the wiki says is missing leads to one search call and,
	 * on a hit whose title shares a word with the title asked for, to the hit's page and its picture (a hit's page that is
	 * itself missing ends the chain with none, with no second search); the picture is kept under the title asked for.
	 */
	void fetch(String title)
	{
		if (title == null || title.trim().isEmpty())
		{
			return;
		}
		synchronized (lock)
		{
			if (cache.containsKey(title) || inFlight.contains(title) || inFlight.size() >= MAX_IN_FLIGHT
				|| !startCall())
			{
				return;
			}
			inFlight.add(title);
		}
		ask(title, requestFor(title), Step.PAGE);
	}

	/**
	 * Counts one call started in the minute, or says there is no room: false when 60 have started in the last minute.
	 * The caller holds {@link #lock}.
	 */
	private boolean startCall()
	{
		final long now = System.nanoTime();
		if (now - windowStart >= MINUTE_NANOS)
		{
			windowStart = now;
			startedInWindow = 0;
		}
		if (startedInWindow >= MAX_PER_MINUTE)
		{
			return false;
		}
		startedInWindow++;
		return true;
	}

	/** Makes one call of a title's chain in the background; its answer goes to {@link #answered}. */
	private void ask(String title, Request request, Step step)
	{
		try
		{
			calls.newCall(request).enqueue(new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					failed(title, e.toString());
				}

				@Override
				public void onResponse(Call call, Response response)
				{
					answered(title, step, response);
				}
			});
		}
		catch (RuntimeException e)
		{
			failed(title, e.toString());
		}
	}

	/**
	 * Reads a 200 answer for the step it was asked in and keeps none for any other answer; the answer is always closed. A
	 * page answer that says the page is missing goes on to the search; a search answer with a hit that is another title and
	 * shares a word with the name goes on to that page; a page answer (the title's own or the hit's) whose thumbnail can be
	 * shown goes on to the picture, and one without ends the chain with none; a picture answer is read, decoded and fitted
	 * here, on the HTTP client's thread, and kept.
	 */
	private void answered(String title, Step step, Response response)
	{
		try (Response answer = response)
		{
			final ResponseBody body = answer.body();
			if (answer.code() != 200 || body == null)
			{
				failed(title, "HTTP " + answer.code());
				return;
			}
			if (step == Step.SEARCH)
			{
				final String nearest = WikiSummaries.firstSearchTitle(body.string(), gson);
				if (nearest == null || nearest.equals(title) || !WikiSummaries.nearEnough(title, nearest))
				{
					finish(title, null);
				}
				else
				{
					next(title, requestFor(nearest), Step.NEAREST);
				}
				return;
			}
			if (step == Step.PAGE || step == Step.NEAREST)
			{
				final String json = body.string();
				if (step == Step.PAGE && WikiSummaries.isMissing(json, gson))
				{
					next(title, WikiSummaries.requestForSearch(title), Step.SEARCH);
					return;
				}
				final HttpUrl address = thumbnailUrl(json, gson);
				if (address == null)
				{
					finish(title, null);
				}
				else
				{
					next(title, requestForPicture(address), Step.PICTURE);
				}
				return;
			}
			// Choice: one byte more than the cap is read, which says the picture is too long without reading the rest of it.
			final byte[] bytes = body.byteStream().readNBytes((int) MAX_BYTES + 1);
			if (bytes.length > MAX_BYTES)
			{
				failed(title, "the picture is over " + MAX_BYTES + " bytes");
				return;
			}
			final BufferedImage picture = decode(bytes);
			if (picture == null)
			{
				failed(title, "the picture could not be decoded");
				return;
			}
			finish(title, fit(picture));
		}
		catch (IOException | RuntimeException e)
		{
			failed(title, e.toString());
		}
	}

	/** Goes on to the next call of a title's chain, or lets the title go unkept when the minute has no room for it. */
	private void next(String title, Request request, Step step)
	{
		synchronized (lock)
		{
			if (!startCall())
			{
				inFlight.remove(title);
				return;
			}
		}
		ask(title, request, step);
	}

	/** Keeps none for the title and says why: one warning the first time, debug lines after. */
	private void failed(String title, String why)
	{
		final boolean first;
		synchronized (lock)
		{
			first = !warned;
			warned = true;
		}
		if (first)
		{
			log.warn("The wiki's picture for a card could not be read ({}); cards show their icon", why);
		}
		else
		{
			log.debug("No wiki picture for '{}': {}", title, why);
		}
		finish(title, null);
	}

	/** Keeps the picture, or none for null, under the title and takes it off the waiting list. */
	private void finish(String title, BufferedImage picture)
	{
		synchronized (lock)
		{
			inFlight.remove(title);
			cache.put(title, picture);
		}
	}

	/** Which call of a title's chain an answer belongs to. */
	private enum Step
	{
		/** The title's own page, asked for its thumbnail. */
		PAGE,
		/** The wiki's search for the title, after its page was missing. */
		SEARCH,
		/** The page the search ranked first, asked for its thumbnail. */
		NEAREST,
		/** The thumbnail's own address. */
		PICTURE
	}
}

package com.clanhub;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The first paragraph of a wiki page, for the cards to show under their rows: the Old School RuneScape Wiki is asked for
 * a page's introduction when a chat line with a card arrives, the answer is kept, and the card reads it from here when it
 * is hovered. What is sent is the page's title ("Goblin champion scroll") and nothing else, to
 * {@code oldschool.runescape.wiki}, through RuneLite's own HTTP client, with a User-Agent that names this plugin; nothing
 * about the player, the line or the world goes with it. The call is asked for in the background ({@code enqueue}, never
 * {@code execute}), so the client thread never waits on the wiki. A title is asked for once: a page that failed, or has
 * no text, is remembered as empty and not asked again. When the wiki says there is no page of that title, its own search
 * is asked once for the name (the name only, the first hit wanted) and the first hit's page is read instead, the
 * paragraph kept under the name the card asked by ("Jubbly Jive Shark" shows the paragraph of "Jubbly Jive Barracuda
 * Trial"), and the hit's page is read only when its title shares a word with the name (see {@link #nearEnough}); the
 * hit's title goes only into the query of that second page call, never into a host or a path. The asking is
 * capped (10 titles at a time, 60 calls a minute, a search counting as a call), and the answers kept are the 500 asked
 * for last.
 *
 * <p>Choice: a failed call is never retried in the same run; one warning is logged the first time a call fails, and the
 * later ones go to the debug log, so a wiki that is down does not fill the log.
 */
final class WikiSummaries
{
	private static final Logger log = LoggerFactory.getLogger(WikiSummaries.class);

	/** The wiki's host; the only one this class talks to, and the one {@link WikiPictures} reads its pictures from. */
	static final String HOST = "oldschool.runescape.wiki";
	/** The User-Agent every call carries, naming the plugin and where its source is; {@link WikiPictures} sends it too. */
	static final String USER_AGENT = "2h Chat Hover Info (RuneLite plugin; github.com/2hBuilds/chat-hover-info)";
	/** How many answers are kept; the oldest go first. */
	private static final int MAX_CACHED = 500;
	/** How many titles may be waiting for an answer at once. */
	private static final int MAX_IN_FLIGHT = 10;
	/** How many calls may be started in one minute. */
	private static final int MAX_PER_MINUTE = 60;
	/** A minute, in {@link System#nanoTime} terms. */
	private static final long MINUTE_NANOS = 60_000_000_000L;
	/** The words {@link #nearEnough} does not count: they would match nearly any two titles. */
	private static final Set<String> FILLER = new HashSet<>(Arrays.asList("the", "and", "of", "for", "with"));

	private final Call.Factory calls;
	private final Gson gson;
	/** Guards everything below: the answers arrive on the HTTP client's thread and are read on the client thread. */
	private final Object lock = new Object();
	/** The paragraphs by title, "" for a page that failed or has none; at most {@link #MAX_CACHED}, the oldest out. */
	private final Map<String, String> cache = new LinkedHashMap<String, String>()
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, String> eldest)
		{
			return size() > MAX_CACHED;
		}
	};
	/** The titles whose chain of calls (page, search, nearest page) has not ended yet. */
	private final Set<String> inFlight = new HashSet<>();
	/** When the current minute began, in {@link System#nanoTime} terms, and how many calls it has started. */
	private long windowStart = System.nanoTime();
	private int startedInWindow;
	/** Whether a failed call has been logged as a warning yet. */
	private boolean warned;

	/**
	 * @param calls where calls are made: RuneLite's own HTTP client (an {@code okhttp3.Call.Factory}), or a stand-in in a test
	 * @param gson RuneLite's Gson, which reads the answer
	 */
	WikiSummaries(Call.Factory calls, Gson gson)
	{
		this.calls = calls;
		this.gson = gson;
	}

	/**
	 * The request for a page's introduction: the wiki's {@code api.php} asked for the page's plain-text extract up to its
	 * first section, redirects followed, as JSON; the title is percent-encoded (a space as %20). It carries this plugin's
	 * User-Agent and nothing about the player.
	 */
	static Request requestFor(String title)
	{
		final HttpUrl url = new HttpUrl.Builder()
			.scheme("https")
			.host(HOST)
			.addPathSegments("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("prop", "extracts")
			.addQueryParameter("exintro", "1")
			.addQueryParameter("explaintext", "1")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("titles", title)
			.build();
		return new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
	}

	/**
	 * The request for the wiki's own search of a name: {@code api.php} asked for the single best hit, as JSON; the name is
	 * percent-encoded (a space as %20). It carries this plugin's User-Agent and nothing about the player.
	 */
	static Request requestForSearch(String title)
	{
		final HttpUrl url = new HttpUrl.Builder()
			.scheme("https")
			.host(HOST)
			.addPathSegments("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("list", "search")
			.addQueryParameter("srsearch", title)
			.addQueryParameter("srlimit", "1")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.build();
		return new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
	}

	/**
	 * The title of the first hit the wiki's search answer holds, or null when there is none. The answer is
	 * {@code {"query": {"search": [{"title": "...", ...}]}}}; no hit is {@code "search": []}. An answer with no search
	 * list, a hit with no title or a blank one, an empty answer, or text that is not JSON gives null.
	 */
	static String firstSearchTitle(String json, Gson gson)
	{
		final JsonObject query = objectOf(parse(json, gson), "query");
		final JsonElement hits = query == null ? null : query.get("search");
		if (hits == null || !hits.isJsonArray() || hits.getAsJsonArray().size() == 0
			|| !hits.getAsJsonArray().get(0).isJsonObject())
		{
			return null;
		}
		final JsonElement title = hits.getAsJsonArray().get(0).getAsJsonObject().get("title");
		if (title == null || !title.isJsonPrimitive() || title.getAsString().trim().isEmpty())
		{
			return null;
		}
		return title.getAsString().trim();
	}

	/**
	 * Whether the wiki's search hit is near enough to the name asked for to be trusted: the two titles share at least one
	 * word. The words are the lower-cased runs of letters and digits in each title; a word shorter than 3 letters and the
	 * words "the", "and", "of", "for" and "with" are not counted; a title with no words left shares none. The examples:
	 * ("Tempor Tantrum Marlin", "The Tempor Tantrum") shares two, so true; ("Jubbly Jive Shark", "Jubbly Jive Barracuda
	 * Trial") true; ("Brutus", "Brutus (Ides of Milk)") true; ("Pandemonium", "Chambers of Xeric") false; ("The", "Of")
	 * false. A hit that is not near enough gives the card nothing, so it never shows another page's words or picture.
	 * {@link WikiPictures} asks it too.
	 */
	static boolean nearEnough(String asked, String hit)
	{
		final Set<String> askedWords = wordsOf(asked);
		if (askedWords.isEmpty())
		{
			return false;
		}
		for (final String word : wordsOf(hit))
		{
			if (askedWords.contains(word))
			{
				return true;
			}
		}
		return false;
	}

	/** The counted words of a title, lower-cased; see {@link #nearEnough}. */
	private static Set<String> wordsOf(String title)
	{
		final Set<String> words = new HashSet<>();
		if (title == null)
		{
			return words;
		}
		for (final String word : title.toLowerCase(Locale.ROOT).split("[^\\p{L}\\p{N}]+"))
		{
			if (word.length() >= 3 && !FILLER.contains(word))
			{
				words.add(word);
			}
		}
		return words;
	}

	/**
	 * Whether the wiki's page answer says the page does not exist: its first page carries {@code "missing": true}. A page
	 * that exists but has no text, an empty answer, or text that is not JSON is not missing.
	 */
	static boolean isMissing(String json, Gson gson)
	{
		final JsonObject page = firstPage(json, gson);
		final JsonElement missing = page == null ? null : page.get("missing");
		return missing != null && missing.isJsonPrimitive() && missing.getAsJsonPrimitive().isBoolean()
			&& missing.getAsBoolean();
	}

	/**
	 * The first paragraph of the page the wiki's answer holds: the first page's {@code extract} up to its first line
	 * break, trimmed. The answer is {@code {"query": {"pages": [{"title": "...", "extract": "..."}]}}}; a page that does
	 * not exist has no extract. Anything else gives an empty text: a missing page, an answer with no pages or no extract,
	 * an empty answer, or text that is not JSON.
	 */
	static String firstParagraph(String json, Gson gson)
	{
		final JsonObject page = firstPage(json, gson);
		final JsonElement extract = page == null ? null : page.get("extract");
		if (extract == null || !extract.isJsonPrimitive())
		{
			return "";
		}
		final String text = extract.getAsString().trim();
		final int lineBreak = text.indexOf('\n');
		return (lineBreak < 0 ? text : text.substring(0, lineBreak)).trim();
	}

	/** The first page of a page answer, or null when the answer has none or is not JSON; {@link WikiPictures} reads it too. */
	static JsonObject firstPage(String json, Gson gson)
	{
		final JsonObject query = objectOf(parse(json, gson), "query");
		final JsonElement pages = query == null ? null : query.get("pages");
		if (pages == null || !pages.isJsonArray())
		{
			return null;
		}
		final JsonArray list = pages.getAsJsonArray();
		if (list.size() == 0 || !list.get(0).isJsonObject())
		{
			return null;
		}
		return list.get(0).getAsJsonObject();
	}

	/** The answer as an object, or null when it is empty, is not JSON, or is not an object. */
	private static JsonObject parse(String json, Gson gson)
	{
		try
		{
			return gson.fromJson(json, JsonObject.class);
		}
		catch (JsonParseException e)
		{
			return null;
		}
	}

	/** A member of an object that is itself an object, or null when it is missing or is something else. */
	private static JsonObject objectOf(JsonObject parent, String member)
	{
		if (parent == null)
		{
			return null;
		}
		final JsonElement child = parent.get(member);
		return child != null && child.isJsonObject() ? child.getAsJsonObject() : null;
	}

	/**
	 * The paragraph kept for a title: the text, an empty text for a page that failed or has none, or null when the title
	 * was never asked for or its answer has not come yet.
	 */
	String summaryOf(String title)
	{
		synchronized (lock)
		{
			return cache.get(title);
		}
	}

	/**
	 * Asks the wiki for a title's first paragraph in the background. Nothing happens when the title is blank, already kept,
	 * already waiting for its answer, when 10 titles are already waiting, or when 60 calls have been started in the last
	 * minute (the title is then asked for again by the next hover). The answer is kept when it arrives: the paragraph on a
	 * 200 answer, an empty text on anything else. A page the wiki says is missing leads to one search call and, on a hit
	 * that is another title, one more page call; that paragraph is kept under the title asked for here. Each of those
	 * calls counts in the minute; when the minute is full before one of them, the title is let go unkept and the next
	 * hover asks again.
	 */
	void fetch(String title)
	{
		if (title == null || title.trim().isEmpty())
		{
			return;
		}
		synchronized (lock)
		{
			if (cache.containsKey(title) || inFlight.contains(title) || inFlight.size() >= MAX_IN_FLIGHT
				|| !startCall())
			{
				return;
			}
			inFlight.add(title);
		}
		ask(title, requestFor(title), Step.PAGE);
	}

	/**
	 * Counts one call started in the minute, or says there is no room: false when 60 have started in the last minute.
	 * The caller holds {@link #lock}.
	 */
	private boolean startCall()
	{
		final long now = System.nanoTime();
		if (now - windowStart >= MINUTE_NANOS)
		{
			windowStart = now;
			startedInWindow = 0;
		}
		if (startedInWindow >= MAX_PER_MINUTE)
		{
			return false;
		}
		startedInWindow++;
		return true;
	}

	/** Makes one call of a title's chain in the background; its answer goes to {@link #answered}. */
	private void ask(String title, Request request, Step step)
	{
		try
		{
			calls.newCall(request).enqueue(new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					failed(title, e.toString());
				}

				@Override
				public void onResponse(Call call, Response response)
				{
					answered(title, step, response);
				}
			});
		}
		catch (RuntimeException e)
		{
			failed(title, e.toString());
		}
	}

	/**
	 * Reads a 200 answer for the step it was asked in and keeps an empty text for any other answer; the answer is always
	 * closed. A page answer that says the page is missing goes on to the search; a search answer with a hit that is
	 * another title and shares a word with the name goes on to that page; any other answer ends the chain.
	 */
	private void answered(String title, Step step, Response response)
	{
		try (Response answer = response)
		{
			final ResponseBody body = answer.body();
			if (answer.code() != 200 || body == null)
			{
				failed(title, "HTTP " + answer.code());
				return;
			}
			final String json = body.string();
			if (step == Step.PAGE && isMissing(json, gson))
			{
				next(title, requestForSearch(title), Step.SEARCH);
			}
			else if (step == Step.SEARCH)
			{
				final String nearest = firstSearchTitle(json, gson);
				if (nearest == null || nearest.equals(title) || !nearEnough(title, nearest))
				{
					finish(title, "");
				}
				else
				{
					next(title, requestFor(nearest), Step.NEAREST);
				}
			}
			else
			{
				finish(title, firstParagraph(json, gson));
			}
		}
		catch (IOException | RuntimeException e)
		{
			failed(title, e.toString());
		}
	}

	/** Goes on to the next call of a title's chain, or lets the title go unkept when the minute has no room for it. */
	private void next(String title, Request request, Step step)
	{
		synchronized (lock)
		{
			if (!startCall())
			{
				inFlight.remove(title);
				return;
			}
		}
		ask(title, request, step);
	}

	/** Keeps an empty text for the title and says why: one warning the first time, debug lines after. */
	private void failed(String title, String why)
	{
		final boolean first;
		synchronized (lock)
		{
			first = !warned;
			warned = true;
		}
		if (first)
		{
			log.warn("The wiki's description for a card could not be read ({}); cards show without it", why);
		}
		else
		{
			log.debug("No wiki description for '{}': {}", title, why);
		}
		finish(title, "");
	}

	/** Keeps the paragraph for the title and takes it off the waiting list. */
	private void finish(String title, String paragraph)
	{
		synchronized (lock)
		{
			inFlight.remove(title);
			cache.put(title, paragraph);
		}
	}

	/** Which call of a title's chain an answer belongs to. */
	private enum Step
	{
		/** The title's own page. */
		PAGE,
		/** The wiki's search for the title, after its page was missing. */
		SEARCH,
		/** The page the search ranked first. */
		NEAREST
	}
}

package com.clanhub;

import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.ChatMessageType;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/** {@link BroadcastItemReader}: a drop line gives its item's card, a source gives the boss's too, other chat gives none. */
public class BroadcastItemReaderTest
{
	// Re-aimed by the lead, 2026-10-08 (lot 8T): the reader takes the tables.
	private static final String LINE = "Klar received a drop: Dragon claws (121,453,000 coins).";

	/** An {@link ItemCards} that answers every name with a card titled by it, at the offsets it was given. */
	private static ItemCards echoing()
	{
		final ItemCards itemCards = Mockito.mock(ItemCards.class);
		when(itemCards.forName(anyString(), anyInt(), anyString(), anyInt(), anyInt())).thenAnswer(call ->
			new ItemCard(0, call.getArgument(0), call.getArgument(1), 0L, 0, call.getArgument(2),
				call.getArgument(3), call.getArgument(4)));
		return itemCards;
	}

	@Test
	public void aDropLineGivesOneCardAndChatterNone()
	{
		final int start = LINE.indexOf("Dragon claws");
		final int end = start + "Dragon claws".length();
		final HoverCard card = new ItemCard(13652, "Dragon claws", 1, 121_453_000L, 123_000, LINE, start, end);
		final ItemCards itemCards = Mockito.mock(ItemCards.class);
		when(itemCards.forName("Dragon claws", 1, LINE, start, end)).thenReturn(card);
		final BroadcastItemReader reader = new BroadcastItemReader(itemCards, () -> true, new CardTables());

		assertEquals(Collections.singletonList(card), reader.read(ChatMessageType.CLAN_MESSAGE, LINE));

		final List<HoverCard> chatter = reader.read(ChatMessageType.CLAN_MESSAGE, "Klar: gz!!!");
		assertTrue("chatter holds no card", chatter.isEmpty());
		verify(itemCards, times(1)).forName(anyString(), anyInt(), anyString(), anyInt(), anyInt());
	}

	@Test
	public void aDropLineWithASourceGivesTheBossCardToo()
	{
		final String duke = "N o r s received a drop: 45 x Runite ore (456,345 coins) from Duke Sucellus.";

		final List<HoverCard> both = new BroadcastItemReader(echoing(), () -> true, new CardTables())
			.read(ChatMessageType.CLAN_MESSAGE, duke);
		assertEquals("the item's card and the boss's", 2, both.size());
		assertTrue("the item first: " + both.get(0).title(), both.get(0).title().contains("Runite ore"));
		assertEquals(45, both.get(0).quantity());
		final HoverCard boss = both.get(1);
		assertTrue("the boss's card is an info card", boss instanceof InfoCard);
		assertEquals("Duke Sucellus", boss.title());
		assertEquals("Duke Sucellus", boss.plainLine().substring(boss.start(), boss.end()));
		assertFalse("quiet, so the item stays the one blue word", boss.marked());
		assertEquals("Duke Sucellus", boss.wikiTitle());
		assertTrue("no facts", boss.rows().isEmpty() || (boss.rows().size() == 1 && boss.rows().get(0).isEmpty()));
		assertTrue("no notes of its own", boss.notes().isEmpty());

		final List<HoverCard> off = new BroadcastItemReader(echoing(), () -> false, new CardTables())
			.read(ChatMessageType.CLAN_MESSAGE, duke);
		assertEquals("with the switch off, the item's card alone", 1, off.size());
		assertTrue(off.get(0).title().contains("Runite ore"));

		final BroadcastItemReader reader = new BroadcastItemReader(echoing(), () -> true, new CardTables());
		assertEquals("a line with no 'from' gives the item's card alone", 1,
			reader.read(ChatMessageType.CLAN_MESSAGE, LINE).size());

		final List<HoverCard> raid = reader.read(ChatMessageType.CLAN_MESSAGE,
			"Klar received a drop: Dragon claws (121,453,000 coins) from Chambers of Xeric.");
		assertEquals(2, raid.size());
		assertEquals("Chambers of Xeric", raid.get(1).title());
	}

	/** The cards fixture's tables with the bosses fixture read into them, as the plugin's own are. */
	private static CardTables fixtureTables() throws Exception
	{
		try (Reader cards = new InputStreamReader(BroadcastItemReaderTest.class.getResourceAsStream(
			"/com/clanhub/cards-fixture.json"), StandardCharsets.UTF_8);
			Reader bosses = new InputStreamReader(BroadcastItemReaderTest.class.getResourceAsStream(
				"/com/clanhub/bosses-fixture.json"), StandardCharsets.UTF_8))
		{
			return CardTables.parse(cards, new Gson()).readBosses(bosses, new Gson());
		}
	}

	// Re-aimed by the lead, 2026-10-08 (lot 8U): the wiki's picture replaces the pet.
	@Test
	public void theBossCardCarriesTheTablesFactsAndAsksForThePicture() throws Exception
	{
		final String duke = "N o r s received a drop: 45 x Runite ore (456,345 coins) from Duke Sucellus.";

		final HoverCard boss = new BroadcastItemReader(echoing(), () -> true, fixtureTables())
			.read(ChatMessageType.CLAN_MESSAGE, duke).get(1);
		assertEquals("one row of facts", 1, boss.rows().size());
		final List<String> facts = new ArrayList<>();
		for (final HoverCard.Pair pair : boss.rows().get(0))
		{
			facts.add(pair.label + " " + pair.value);
		}
		assertEquals(Arrays.asList("Combat 450", "Hitpoints 440", "Max hit 24",
			"Quest Desert Treasure II - The Fallen Empire"), facts);
		assertEquals("no pet: the wiki's picture replaces it", -1, boss.itemId());
		assertTrue("the card asks for the wiki's picture", boss.wikiPicture());
		assertEquals("the combat sprite stands behind it", SkillSprites.spriteOf("Combat"), boss.spriteId());
		assertEquals("Duke Sucellus", boss.title());
		assertEquals("Duke Sucellus", boss.plainLine().substring(boss.start(), boss.end()));
		assertEquals("the wiki page is the table's", "https://oldschool.runescape.wiki/w/Duke_Sucellus", boss.wikiUrl());
		assertFalse("still quiet", boss.marked());

		final HoverCard bare = new BroadcastItemReader(echoing(), () -> true, new CardTables())
			.read(ChatMessageType.CLAN_MESSAGE, duke).get(1);
		assertTrue("a table that has not loaded gives no facts", bare.rows().get(0).isEmpty());
		assertEquals("and no pet", -1, bare.itemId());
		assertTrue("the wiki's picture is asked for all the same", bare.wikiPicture());
		assertEquals("the combat sprite is the picture, as in lot 8R", SkillSprites.spriteOf("Combat"), bare.spriteId());

		final HoverCard unknown = new BroadcastItemReader(echoing(), () -> true, fixtureTables())
			.read(ChatMessageType.CLAN_MESSAGE, "Klar received a drop: Dragon claws (121,453,000 coins) from Nobody.")
			.get(1);
		assertTrue("a boss the table lacks gives no facts", unknown.rows().get(0).isEmpty());
		assertEquals(-1, unknown.itemId());
		assertTrue("and still asks for the wiki's picture", unknown.wikiPicture());
		assertEquals("with the combat sprite behind it", SkillSprites.spriteOf("Combat"), unknown.spriteId());
		assertEquals("Nobody", unknown.wikiTitle());
	}
}

package com.clanhub;

import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * {@link BroadcastKindReader}: the quest, task, pet, level, XP, diary and personal best broadcasts and the player's own
 * kill count each give their card, raid loot gives the item card, and every other line, a combat level or total level
 * line among them, gives nothing.
 */
public class BroadcastKindReaderTest
{
	private static final String QUEST_LINE = "Klar has completed a quest: Dragon Slayer II";

	/** The tables of the fixture, read the way the plugin reads its own. */
	private static CardTables fixtureTables() throws Exception
	{
		try (Reader in = new InputStreamReader(BroadcastKindReaderTest.class.getResourceAsStream(
			"/com/clanhub/cards-fixture.json"), StandardCharsets.UTF_8))
		{
			return CardTables.parse(in, new Gson());
		}
	}

	/** A reader with the fixture's tables over the given item cards. */
	private static BroadcastKindReader reader(ItemCards itemCards) throws Exception
	{
		return new BroadcastKindReader(fixtureTables(), itemCards);
	}

	/** The row as the card shows it: each pair as its label and value, the pairs set apart by commas. */
	private static String rowOf(HoverCard card)
	{
		assertEquals("one row", 1, card.rows().size());
		final List<String> pairs = new ArrayList<>();
		for (final HoverCard.Pair pair : card.rows().get(0))
		{
			pairs.add((pair.label + " " + pair.value).trim());
		}
		return String.join(", ", pairs);
	}

	/** The one card a line of the type gives. */
	private static HoverCard theCard(BroadcastKindReader reader, ChatMessageType type, String line)
	{
		final List<HoverCard> cards = reader.read(type, line);
		assertEquals("one card from: " + line, 1, cards.size());
		return cards.get(0);
	}

	@Test
	public void questAndCombatTaskLines() throws Exception
	{
		final BroadcastKindReader reader = reader(Mockito.mock(ItemCards.class));

		final HoverCard quest = theCard(reader, ChatMessageType.CLAN_MESSAGE, QUEST_LINE);
		assertEquals("Dragon Slayer II", quest.title());
		assertEquals("Difficulty Grandmaster, Length Very Long, Points 5", rowOf(quest));
		assertEquals(899, quest.spriteId());
		assertTrue(quest.wikiUrl().endsWith("/w/Dragon_Slayer_II"));
		assertEquals(28, quest.start());
		assertEquals(44, quest.end());
		assertEquals(QUEST_LINE, quest.plainLine());
		assertTrue(quest.notes().isEmpty());
		assertTrue("a quest name is coloured in the chat", quest.marked());

		final HoverCard task = theCard(reader, ChatMessageType.CLAN_MESSAGE,
			"CA_ID:279|Klar has completed a Master combat task: Perfect Zulrah (5 points).");
		assertEquals("Perfect Zulrah", task.title());
		assertEquals("Tier Master, Points 5, Boss Zulrah", rowOf(task));
		// Re-aimed by the lead, 2026-10-08 (lot 8L): the description is one whole note; the painter wraps it.
		assertEquals(Collections.singletonList("Kill Zulrah whilst taking no damage from the following: Snakelings, "
			+ "Venom Clouds, Zulrah's Green or Crimson phase."), task.notes());
		assertEquals(3397, task.spriteId());
		assertEquals("Perfect Zulrah", task.plainLine().substring(task.start(), task.end()));
		assertTrue(task.wikiUrl().endsWith("/w/Perfect_Zulrah"));
		assertTrue("a task name is coloured in the chat", task.marked());

		final HoverCard plain = theCard(reader, ChatMessageType.CLAN_MESSAGE,
			"Klar has completed a quest: Made Up Quest");
		assertEquals("Made Up Quest", plain.title());
		assertEquals("Quest completed", rowOf(plain));
		assertTrue(plain.wikiUrl().endsWith("/w/Made_Up_Quest"));

		final HoverCard unknownTask = theCard(reader, ChatMessageType.CLAN_GIM_MESSAGE,
			"CA_ID:5|Klar has completed an Easy combat task: Made Up Task.");
		assertEquals("Made Up Task", unknownTask.title());
		assertEquals("Tier Easy", rowOf(unknownTask));
		assertEquals(3393, unknownTask.spriteId());
		assertTrue(unknownTask.notes().isEmpty());

		final BroadcastKindReader unloaded = new BroadcastKindReader(new CardTables(), Mockito.mock(ItemCards.class));
		final HoverCard early = theCard(unloaded, ChatMessageType.FRIENDSCHATNOTIFICATION, QUEST_LINE);
		assertEquals("Quest completed", rowOf(early));
		assertTrue(early.wikiUrl().endsWith("/w/Dragon_Slayer_II"));
	}

	@Test
	public void aQuestLineWithAStringVariableGivesTheQuestCard() throws Exception
	{
		final BroadcastKindReader reader = reader(Mockito.mock(ItemCards.class));
		final String plain = "Small Za has completed a quest: King's Ransom";
		final String raw = "<img=2> <str_quest_name_0=King's Ransom>Small Za has completed a quest: "
			+ "<str_quest_name_0>";

		final HoverCard quest = theCard(reader, ChatMessageType.CLAN_MESSAGE, raw);
		assertEquals(plain, quest.plainLine());
		assertEquals("King's Ransom", quest.plainLine().substring(quest.start(), quest.end()));
		assertTrue("a quest name is coloured in the chat", quest.marked());

		final HoverCard literal = theCard(reader, ChatMessageType.CLAN_MESSAGE, plain);
		assertEquals("King's Ransom", quest.title());
		assertEquals("the card of the quest written out", literal.title(), quest.title());
		assertEquals(rowOf(literal), rowOf(quest));
		assertEquals(literal.spriteId(), quest.spriteId());
		assertEquals(literal.wikiUrl(), quest.wikiUrl());
	}

	@Test
	public void petLevelTotalXpDiaryAndPersonalBestLines() throws Exception
	{
		final BroadcastKindReader reader = reader(Mockito.mock(ItemCards.class));
		final ChatMessageType clan = ChatMessageType.CLAN_MESSAGE;

