package com.clanhub;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.CommandExecuted;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;

/** {@link DemoCommand}: the sample lines are posted in developer mode for {@code ::hoverinfo demo} and nowhere else. */
public class DemoCommandTest
{
	private static CommandExecuted command(String name, String... arguments)
	{
		return new CommandExecuted(name, arguments);
	}

	// Re-aimed by the lead, 2026-10-08 (lot 8M): the name is 2h Chat Hover Info and the command ::hoverinfo.
	@Test
	public void postsTheSampleLinesOnlyInDeveloperMode()
	{
		final Client off = Mockito.mock(Client.class);
		assertEquals("a Hub build does nothing", 0, DemoCommand.run(off, false, command("hoverinfo", "demo")));
		verifyNoInteractions(off);

		final Client on = Mockito.mock(Client.class);
		assertEquals(DemoLines.lines().size(), DemoCommand.run(on, true, command("hoverinfo", "demo")));
		assertTrue("the item samples are posted", DemoLines.lines().size() >= DemoLines.ITEMS.size());
		for (final DemoLines.Line line : DemoLines.lines())
		{
			// A clan or friends line is posted from "2h Chat Hover Info"; a public chat or game line has no channel name.
			final boolean typedOrGame = line.type == ChatMessageType.PUBLICCHAT || line.type == ChatMessageType.GAMEMESSAGE;
			verify(on).addChatMessage(line.type, line.name, line.text, typedOrGame ? "" : "2h Chat Hover Info", true);
		}

		final Client bare = Mockito.mock(Client.class);
		assertEquals(0, DemoCommand.run(bare, true, command("hoverinfo")));
		verifyNoInteractions(bare);

		final Client other = Mockito.mock(Client.class);
		assertEquals(0, DemoCommand.run(other, true, command("hoverinfo", "show")));
		verifyNoInteractions(other);
	}

	/** Lot 8Y: {@code ::hoverinfo trace} is read in developer mode only, in any case, and posts no sample line. */
	@Test
	public void theTraceWordIsReadOnlyInDeveloperMode()
	{
		assertTrue(DemoCommand.isTrace(true, command("hoverinfo", "trace")));
		assertTrue("any case", DemoCommand.isTrace(true, command("HoverInfo", "TRACE")));
		assertFalse("a Hub build", DemoCommand.isTrace(false, command("hoverinfo", "trace")));
		assertFalse("the demo word", DemoCommand.isTrace(true, command("hoverinfo", "demo")));
		assertFalse("no arguments", DemoCommand.isTrace(true, command("hoverinfo")));
		assertFalse("another command", DemoCommand.isTrace(true, command("other", "trace")));

		final Client client = Mockito.mock(Client.class);
		assertEquals("the trace word posts no sample line", 0, DemoCommand.run(client, true, command("hoverinfo", "trace")));
		verifyNoInteractions(client);
	}
}

package com.clanhub;

import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.List;
import java.util.Optional;
import net.runelite.api.ChatMessageType;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.when;

/** {@link DemoLines}: the item samples are broadcasts the reader reads, and they lead the list of every sample. */
public class DemoLinesTest
{
	@Test
	public void everyItemSampleIsABroadcastTheReaderReads()
	{
		// Re-aimed by the lead, 2026-10-08 (lot 8R): a fifth item line, the drop that says where it came from.
		final List<String> expected = Arrays.asList("Dragon claws", "Black knife", "Ranger boots", "Abyssal whip",
			"Runite ore");
		assertEquals(expected.size(), DemoLines.ITEMS.size());
		for (int i = 0; i < DemoLines.ITEMS.size(); i++)
		{
			final DemoLines.Line line = DemoLines.ITEMS.get(i);
			final Optional<BroadcastLine.ItemMention> found = BroadcastLine.parse(line.type, line.text);
			assertTrue("a mention in: " + line.text, found.isPresent());
			assertEquals(expected.get(i), found.get().name);
			assertEquals("a broadcast has no speaker", "", line.name);
		}

		final List<DemoLines.Line> all = DemoLines.lines();
		assertTrue("lines() holds at least the five", all.size() >= DemoLines.ITEMS.size());
		assertEquals("lines() starts with the five", DemoLines.ITEMS, all.subList(0, DemoLines.ITEMS.size()));
		assertTrue("the fifth names its boss", DemoLines.ITEMS.get(4).text.endsWith("from Duke Sucellus."));
	}

	@Test
	public void theOwnSamplesFollowTheItems()
	{
		// Re-aimed by the lead, 2026-10-08 (lot 8e): player chat is never read, so the demo has no typed line.
		final List<DemoLines.Line> all = DemoLines.lines();
		final int items = DemoLines.ITEMS.size();
		assertEquals(2, DemoLines.OWN.size());
		assertEquals("the own lines follow the items", DemoLines.OWN, all.subList(items, items + 2));
		// Re-aimed by the lead, 2026-10-08 (lot 8R): the fifth item line makes 16 in all.
		// Re-aimed by the lead, 2026-10-08 (lot 8V): combat level and total level lines give no card, so 14 in all.
		// Re-aimed by the lead, 2026-10-09 (lot 9E): a second quest line, in the game's string-variable form.
		// Re-aimed by the lead, 2026-10-25 (lot 10O): the own level-up line.
		assertEquals("16 lines in all", 16, all.size());

		final ItemCards itemCards = Mockito.mock(ItemCards.class);
		when(itemCards.forName(anyString(), anyInt(), anyString(), anyInt(), anyInt())).thenAnswer(call ->
			new ItemCard(0, call.getArgument(0), call.getArgument(1), 0L, 0, call.getArgument(2),
				call.getArgument(3), call.getArgument(4)));
		// Re-aimed by the lead, 2026-10-08 (lot 8T): the reader takes the tables.
		final OwnLineReader reader = new OwnLineReader(itemCards, () -> true, new CardTables());
		for (final DemoLines.Line line : DemoLines.OWN)
		{
			assertEquals(ChatMessageType.GAMEMESSAGE, line.type);
			assertEquals("an own game line has no speaker", "", line.name);
			assertEquals("one card from: " + line.text, 1, reader.read(line.type, line.text).size());
		}
	}

	@Test
	public void theKindSamplesEndTheList() throws Exception
	{
		// Re-aimed by the lead, 2026-10-08 (lot 8V): combat level and total level lines give no card, so seven kinds.
		// Re-aimed by the lead, 2026-10-09 (lot 9E): a second quest line, in the game's string-variable form.
		// Re-aimed by the lead, 2026-10-25 (lot 10O): the own level-up line.
		assertEquals(9, DemoLines.KINDS.size());
		for (int i = 0; i < DemoLines.KINDS.size(); i++)
		{
			final DemoLines.Line line = DemoLines.KINDS.get(i);
			assertEquals(i < 8 ? ChatMessageType.CLAN_MESSAGE : ChatMessageType.GAMEMESSAGE, line.type);
			assertEquals("a broadcast has no speaker", "", line.name);
		}
		assertEquals("the ninth is the own Sailing level-up",
			"Congratulations, you've just advanced your Sailing level. You are now level 47.", DemoLines.KINDS.get(8).text);
		final List<DemoLines.Line> all = DemoLines.lines();
		assertEquals("lines() ends with the kinds", DemoLines.KINDS, all.subList(all.size() - 9, all.size()));

		final CardTables tables;
		try (Reader in = new InputStreamReader(DemoLinesTest.class.getResourceAsStream("/com/clanhub/cards-fixture.json"),
			StandardCharsets.UTF_8))
		{
			tables = CardTables.parse(in, new Gson());
		}
		final BroadcastKindReader reader = new BroadcastKindReader(tables, Mockito.mock(ItemCards.class));
		for (final DemoLines.Line line : DemoLines.KINDS)
		{
			assertTrue("a card from: " + line.text, reader.read(line.type, line.text).size() >= 1);
		}
	}
}

package com.clanhub;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;
import org.junit.Assume;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** {@link DropRates}: the table's shape read from a small fixture, an empty table, and the real bundled table. */
public class DropRatesTest
{
	private static final String FIXTURE = "/com/clanhub/drops-fixture.json";
	private static final String BUNDLED = "/com/clanhub/drops.json";

	/** A classpath resource opened as the plugin opens its table: read as UTF-8. */
	private static Reader open(String resource)
	{
		return new InputStreamReader(DropRatesTest.class.getResourceAsStream(resource), StandardCharsets.UTF_8);
	}

	@Test
	public void parsesTheFixtureAndAnswersByName() throws Exception
	{
		final DropRates rates;
		try (Reader in = open(FIXTURE))
		{
			rates = DropRates.parse(in, new Gson());
		}

		final List<DropRates.DropSource> whip = rates.lookup("Abyssal whip");
		assertEquals(2, whip.size());
		assertEquals("Abyssal demon", whip.get(0).from);
		assertEquals("1/512", whip.get(0).rate);
		assertEquals("Abyssal_demon", whip.get(0).wiki);
		assertEquals("Greater abyssal demon", whip.get(1).from);

		final List<DropRates.DropSource> lower = rates.lookup("abyssal whip");
		assertEquals(2, lower.size());
		assertEquals("Abyssal demon", lower.get(0).from);
		assertEquals("1/512", lower.get(0).rate);
		assertEquals("Abyssal_demon", lower.get(0).wiki);

		assertTrue(rates.lookup("Nonsense").isEmpty());
		assertTrue(rates.loaded());
	}

	@Test
	public void anEmptyTableAnswersNothingWithoutFailing()
	{
		final DropRates none = new DropRates();
		assertFalse(none.loaded());
		assertTrue(none.lookup("Dragon claws").isEmpty());

		final DropRates empty = DropRates.parse(new StringReader("{\"items\": {}}"), new Gson());
		assertTrue(empty.loaded());
		assertTrue(empty.lookup("Dragon claws").isEmpty());
	}

	/**
	 * Choice: the items are counted from the file's own list of names (read with a Gson of the test's own), each name
	 * asked of the parsed table, so the count is of items the table answers for and no member exists for the test alone.
	 */
	@Test
	public void theBundledTableParsesWhenItIsThere() throws Exception
	{
		Assume.assumeNotNull(DropRates.class.getResource(BUNDLED));
		final Gson gson = new Gson();
		final DropRates rates;
		try (Reader in = open(BUNDLED))
		{
			rates = DropRates.parse(in, gson);
		}
		final JsonObject root;
		try (Reader in = open(BUNDLED))
		{
			root = gson.fromJson(in, JsonObject.class);
		}

		int items = 0;
		for (final Map.Entry<String, JsonElement> item : root.getAsJsonObject("items").entrySet())
		{
			final List<DropRates.DropSource> sources = rates.lookup(item.getKey());
			if (!sources.isEmpty())
			{
				items++;
			}
			for (final DropRates.DropSource source : sources)
			{
				assertFalse("a source without a name for " + item.getKey(), source.from.isEmpty());
				assertFalse("a source without a rate for " + item.getKey(), source.rate.isEmpty());
			}
		}
		assertTrue("at least 1,000 items, found " + items, items >= 1000);
		assertFalse("the whip has a source", rates.lookup("Abyssal whip").isEmpty());
	}
}

package com.clanhub;

import java.awt.Color;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** {@link ExamineGlyph}, in memory: its size, its transparent corner and the colour of its ink. */
public class ExamineGlyphTest
{
	private static final Color ORANGE = new Color(220, 138, 0);

	/** How many pixels of {@code img} are fully opaque and exactly {@code colour}. */
	private static int inkOf(BufferedImage img, Color colour)
	{
		int count = 0;
		for (int y = 0; y < img.getHeight(); y++)
		{
			for (int x = 0; x < img.getWidth(); x++)
			{
				if (img.getRGB(x, y) == (0xFF000000 | colour.getRGB()))
				{
					count++;
				}
			}
		}
		return count;
	}

	/** Lot 10E: the glass is as big as asked, has some pixels of the colour, and its corner is transparent. */
	@Test
	public void theGlassIsDrawnInTheSizeAskedFor()
	{
		final ImageIcon icon = ExamineGlyph.icon(20, ORANGE);
		assertEquals(20, icon.getIconWidth());
		assertEquals(20, icon.getIconHeight());
		final BufferedImage img = (BufferedImage) icon.getImage();
		assertEquals(20, img.getWidth());
		assertEquals(20, img.getHeight());
		assertTrue("some pixels of the colour", inkOf(img, ORANGE) > 10);
		assertEquals("the top right corner is transparent", 0, img.getRGB(19, 0) >>> 24);
		assertEquals("so is the top left", 0, img.getRGB(0, 0) >>> 24);
		assertEquals("so is the bottom left", 0, img.getRGB(0, 19) >>> 24);
		assertEquals("so is the bottom right", 0, img.getRGB(19, 19) >>> 24);
	}

	@Test
	public void noColourMeansTheSidebarsGreyAndTheSizeHasAFloor()
	{
		final BufferedImage grey = (BufferedImage) ExamineGlyph.icon(20, null).getImage();
		assertTrue("the quiet grey", inkOf(grey, ColorScheme.LIGHT_GRAY_COLOR) > 10);
		assertEquals(ExamineGlyph.MIN_SIZE, ExamineGlyph.icon(2, ORANGE).getIconWidth());
	}
}

package com.clanhub;

import com.clanhub.ClanHubConfig.ExamineLine;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.game.ItemManager;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

/**
 * {@link ExamineReader}: the click on Examine names the thing, and the examine line that follows within two game ticks
 * gets its card, once.
 */
public class ExamineReaderTest
{
	private static final String WHIP_LINE = "A weapon from the abyss.";
	private static final String VORKATH_LINE = "Azure and ancient.";

	/** The game tick the reader is told, which a test moves. */
	private final int[] now = {100};
	/** Whether the "Examine cards" setting is on, which a test flips. */
	private final boolean[] on = {true};
	/** How an examine line reads, which a test sets. */
	private final ExamineLine[] style = {ExamineLine.NAME_FIRST};

	/** An {@link ItemManager} that knows the abyssal whip (and its noted form), and an id the game has no name for. */
	private static ItemCards itemCards()
	{
		final ItemManager itemManager = Mockito.mock(ItemManager.class);
		when(itemManager.canonicalize(4151)).thenReturn(4151);
		when(itemManager.canonicalize(4152)).thenReturn(4151);
		when(itemManager.canonicalize(77)).thenReturn(77);
		final ItemComposition whip = Mockito.mock(ItemComposition.class);
		when(whip.getName()).thenReturn("Abyssal whip");
		when(whip.getHaPrice()).thenReturn(72_000);
		when(itemManager.getItemComposition(4151)).thenReturn(whip);
		when(itemManager.getItemPrice(4151)).thenReturn(1_500_000L);
		final ItemComposition nothing = Mockito.mock(ItemComposition.class);
		when(nothing.getName()).thenReturn("null");
		when(itemManager.getItemComposition(77)).thenReturn(nothing);
		return new ItemCards(itemManager);
	}

	private ExamineReader reader()
	{
		return new ExamineReader(itemCards(), new CardTables(), () -> on[0], () -> now[0], () -> style[0]);
	}

	/** A menu click, answering what the reader asks of one. */
	private static MenuOptionClicked click(String option, String target, MenuAction action, int id, int itemId, NPC npc)
	{
		final MenuOptionClicked event = Mockito.mock(MenuOptionClicked.class);
		when(event.getMenuOption()).thenReturn(option);
		when(event.getMenuTarget()).thenReturn(target);
		when(event.getMenuAction()).thenReturn(action);
		when(event.getId()).thenReturn(id);
		when(event.getItemId()).thenReturn(itemId);
		final MenuEntry entry = Mockito.mock(MenuEntry.class);
		when(entry.getNpc()).thenReturn(npc);
		when(event.getMenuEntry()).thenReturn(entry);
		return event;
	}

	@Test
	public void anItemClickThenItsExamineLineGivesTheItemsCard()
	{
		final ExamineReader reader = reader();

		reader.itemExamined(4151);
		final List<HoverCard> cards = reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE);

		assertEquals("one card", 1, cards.size());
		final HoverCard card = cards.get(0);
		assertEquals("Abyssal whip", card.title());
		assertEquals(WHIP_LINE, card.plainLine());
		assertEquals("the whole text is the hover words, from its start", 0, card.start());
		assertEquals("to its end", WHIP_LINE.length(), card.end());
		assertTrue("marked", card.marked());
		assertEquals("the item's price", 1_500_000L, ((ItemCard) card).price);
		assertEquals("the item's high alchemy value", 72_000, ((ItemCard) card).alch);
		assertTrue("one click, one card: the same line again gives nothing",
			reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE).isEmpty());
	}

	@Test
	public void aLineWithoutAFreshClickGivesNothing()
	{
		final ExamineReader reader = reader();
		assertTrue("no click: nothing", reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE).isEmpty());

		reader.itemExamined(4151);
		now[0] = 103;
		assertTrue("a click at 100 read at 103: nothing", reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE).isEmpty());

		now[0] = 100;
		reader.itemExamined(4151);
		now[0] = 102;
		assertEquals("a click at 100 read at 102: the card", 1, reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE).size());

		now[0] = 100;
		reader.itemExamined(4151);
		now[0] = 99;
		assertTrue("a click from the future: nothing", reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE).isEmpty());

		now[0] = 100;
		reader.itemExamined(4151);
		assertTrue("a game message after the click: nothing",
			reader.read(ChatMessageType.GAMEMESSAGE, WHIP_LINE).isEmpty());
		assertTrue("a monster's examine line after an item click: nothing",
			reader.read(ChatMessageType.NPC_EXAMINE, VORKATH_LINE).isEmpty());
		assertEquals("and the item's own line after them still gives the card", 1,
			reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE).size());
	}

	@Test
	public void aNotedItemGivesTheItemItself()
	{
		final ExamineReader reader = reader();

		reader.itemExamined(4152);
		final List<HoverCard> cards = reader.read(ChatMessageType.ITEM_EXAMINE, "Swap this note at any bank for the equivalent item.");
		assertEquals(1, cards.size());
		assertEquals("the note gives the item itself", "Abyssal whip", cards.get(0).title());
		assertEquals(4151, ((ItemCard) cards.get(0)).id);
		assertEquals("and its picture is the item's", 4151, cards.get(0).itemId());

		reader.itemExamined(77);
		assertTrue("an id the game has no name for: nothing", reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE).isEmpty());
	}

	@Test
	public void aMonsterClickGivesItsCard()
	{
		final ExamineReader reader = reader();

		reader.npcExamined("Vorkath");
		final List<HoverCard> cards = reader.read(ChatMessageType.NPC_EXAMINE, VORKATH_LINE);

		assertEquals("one card", 1, cards.size());
		final HoverCard card = cards.get(0);
		assertEquals("Vorkath", card.title());
		assertTrue("marked", card.marked());
		assertTrue("with the wiki's picture", card.wikiPicture());
		assertEquals(VORKATH_LINE, card.plainLine());
		assertEquals(0, card.start());
		assertEquals(VORKATH_LINE.length(), card.end());
		assertTrue("a table with no such boss gives no facts", card.rows().get(0).isEmpty());
		assertEquals("Vorkath", card.wikiTitle());
		assertTrue("one click, one card", reader.read(ChatMessageType.NPC_EXAMINE, VORKATH_LINE).isEmpty());
	}

	@Test
	public void aBossTheTableKnowsGivesItsFacts() throws Exception
	{
		final CardTables tables;
		try (Reader cards = new InputStreamReader(ExamineReaderTest.class.getResourceAsStream(
			"/com/clanhub/cards-fixture.json"), StandardCharsets.UTF_8);
			Reader bosses = new InputStreamReader(ExamineReaderTest.class.getResourceAsStream(
				"/com/clanhub/bosses-fixture.json"), StandardCharsets.UTF_8))
		{
			tables = CardTables.parse(cards, new Gson()).readBosses(bosses, new Gson());
		}
		final ExamineReader reader = new ExamineReader(itemCards(), tables, () -> true, () -> now[0],
			() -> style[0]);

		reader.npcExamined("Duke Sucellus");
		final HoverCard card = reader.read(ChatMessageType.NPC_EXAMINE, "A vampyric Duke.").get(0);

		final List<String> facts = new ArrayList<>();
		for (final HoverCard.Pair pair : card.rows().get(0))
		{
			facts.add(pair.label + " " + pair.value);
		}
		assertEquals(Arrays.asList("Combat 450", "Hitpoints 440", "Max hit 24",
			"Quest Desert Treasure II - The Fallen Empire"), facts);
	}

	@Test
	public void theSwitchOffGivesNothing()
	{
		final ExamineReader reader = reader();

		on[0] = false;
		reader.itemExamined(4151);
		assertTrue("off: an item click and its line give nothing",
			reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE).isEmpty());

		on[0] = true;
		reader.itemExamined(4151);
		assertEquals("on again, a new click and its line give the card", 1,
			reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE).size());
	}

	/** Lot 10B: the name goes in front of the text, and the card's words are the name alone. */
	@Test
	public void nameFirstPutsTheNameInFrontAndHoversIt()
	{
		final ExamineReader reader = reader();
		style[0] = ExamineLine.NAME_FIRST;
		final String labelled = "Abyssal whip: " + WHIP_LINE;

		reader.itemExamined(4151);
		assertEquals("the name, a colon and the text", labelled, reader.label(ChatMessageType.ITEM_EXAMINE, WHIP_LINE));
		assertEquals("labelling forgets nothing: asked again, the same", labelled,
			reader.label(ChatMessageType.ITEM_EXAMINE, WHIP_LINE));

		final List<HoverCard> cards = reader.read(ChatMessageType.ITEM_EXAMINE, labelled);
		assertEquals("one card", 1, cards.size());
		final HoverCard card = cards.get(0);
		assertEquals(labelled, card.plainLine());
		assertEquals("the hover words start at the name", 0, card.start());
		assertEquals("and end with it", 12, card.end());
		assertEquals("Abyssal whip", card.title());
		assertTrue("one click, one card: the same line again gives nothing",
			reader.read(ChatMessageType.ITEM_EXAMINE, labelled).isEmpty());
	}

	/** Lot 10B: with the style at 'Description only' the line stays as it came and all of it is the hover words. */
	@Test
	public void descriptionOnlyLeavesTheLine()
	{
		final ExamineReader reader = reader();
		style[0] = ExamineLine.DESCRIPTION;

		reader.itemExamined(4151);
		assertEquals("the line is unchanged", WHIP_LINE, reader.label(ChatMessageType.ITEM_EXAMINE, WHIP_LINE));

		final List<HoverCard> cards = reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE);
		assertEquals("one card", 1, cards.size());
		assertEquals("over the whole text, from its start", 0, cards.get(0).start());
		assertEquals("to its end", WHIP_LINE.length(), cards.get(0).end());
	}

	/** Lot 10B: a line that answers no fresh click of its kind is never given a name. */
	@Test
	public void noFreshClickNeverChangesTheLine()
	{
		final ExamineReader reader = reader();
		style[0] = ExamineLine.NAME_FIRST;
		assertEquals("no click: unchanged", WHIP_LINE, reader.label(ChatMessageType.ITEM_EXAMINE, WHIP_LINE));

		reader.itemExamined(4151);
		now[0] = 103;
		assertEquals("a click at 100 labelled at 103: unchanged", WHIP_LINE,
			reader.label(ChatMessageType.ITEM_EXAMINE, WHIP_LINE));

		now[0] = 100;
		on[0] = false;
		reader.itemExamined(4151);
		assertEquals("'Examine cards' off: unchanged", WHIP_LINE, reader.label(ChatMessageType.ITEM_EXAMINE, WHIP_LINE));

		on[0] = true;
		assertEquals("a game message after the item click: unchanged", WHIP_LINE,
			reader.label(ChatMessageType.GAMEMESSAGE, WHIP_LINE));
		assertEquals("a monster's line after the item click: unchanged", VORKATH_LINE,
			reader.label(ChatMessageType.NPC_EXAMINE, VORKATH_LINE));

		reader.itemExamined(77);
		assertEquals("an item whose name is 'null': unchanged", WHIP_LINE,
			reader.label(ChatMessageType.ITEM_EXAMINE, WHIP_LINE));

		reader.itemExamined(4151);
		assertNull("a null message is null", reader.label(ChatMessageType.ITEM_EXAMINE, null));
	}

	/** Lot 10B: a monster's line gets the monster's name in front too. */
	@Test
	public void aMonsterNameFirst()
	{
		final ExamineReader reader = reader();
		style[0] = ExamineLine.NAME_FIRST;
		final String labelled = "Vorkath: " + VORKATH_LINE;

		reader.npcExamined("Vorkath");
		assertEquals(labelled, reader.label(ChatMessageType.NPC_EXAMINE, VORKATH_LINE));

		final List<HoverCard> cards = reader.read(ChatMessageType.NPC_EXAMINE, labelled);
		assertEquals("one card", 1, cards.size());
		final HoverCard card = cards.get(0);
		assertEquals("Vorkath", card.title());
		assertEquals(labelled, card.plainLine());
		assertEquals("the hover words start at the name", 0, card.start());
		assertEquals("and end with it", 7, card.end());
		assertTrue("with the wiki's picture", card.wikiPicture());
	}

	@Test
	public void theClickIsReadFromTheMenu()
	{
		// An examine of an item on the ground.
		ExamineReader reader = reader();
		ExamineReader.clicked(reader, click("Examine", "<col=ff9040>Abyssal whip", MenuAction.EXAMINE_ITEM_GROUND, 4151, -1, null));
		List<HoverCard> cards = reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE);
		assertEquals("a ground item remembers its id", 1, cards.size());
		assertEquals("Abyssal whip", cards.get(0).title());

		// Another option on the same item is not an examine.
		reader = reader();
		ExamineReader.clicked(reader, click("Use", "<col=ff9040>Abyssal whip", MenuAction.CC_OP, 0, 4151, null));
		assertTrue("'Use' remembers nothing", reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE).isEmpty());

		// An examine of an item in the inventory, the bank or the worn items arrives as a widget action with the item's id.
		reader = reader();
		ExamineReader.clicked(reader, click("Examine", "<col=ff9040>Abyssal whip", MenuAction.CC_OP, 0, 4151, null));
		cards = reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE);
		assertEquals("a widget item remembers the item's id", 1, cards.size());
		assertEquals("Abyssal whip", cards.get(0).title());

		// An examine of a monster the menu entry has no NPC for: the name comes from the target.
		reader = reader();
		ExamineReader.clicked(reader, click("Examine", "<col=ffff00>Vorkath<col=ff00>  (level-732)", MenuAction.EXAMINE_NPC,
			0, -1, null));
		cards = reader.read(ChatMessageType.NPC_EXAMINE, VORKATH_LINE);
		assertEquals("a monster remembers its name", 1, cards.size());
		assertEquals("without its tags and its level", "Vorkath", cards.get(0).title());

		// A non-breaking space in a name reads as a space.
		reader = reader();
		ExamineReader.clicked(reader, click("Examine", "<col=ffff00>Giant\u00a0spider<col=ff00>  (level-2)",
			MenuAction.EXAMINE_NPC, 0, -1, null));
		assertEquals("Giant spider", reader.read(ChatMessageType.NPC_EXAMINE, "Incredibly large.").get(0).title());

		// The menu entry's NPC is asked first.
		reader = reader();
		final NPC npc = Mockito.mock(NPC.class);
		when(npc.getName()).thenReturn("Zulrah");
		ExamineReader.clicked(reader, click("Examine", "<col=ffff00>Snakeling", MenuAction.EXAMINE_NPC, 0, -1, npc));
		assertEquals("Zulrah", reader.read(ChatMessageType.NPC_EXAMINE, "A serpent.").get(0).title());

		// An examine of an object forgets what was remembered before it.
		reader = reader();
		ExamineReader.clicked(reader, click("Examine", "<col=ff9040>Abyssal whip", MenuAction.EXAMINE_ITEM_GROUND, 4151, -1, null));
		ExamineReader.clicked(reader, click("Examine", "<col=ffff>Bank booth", MenuAction.EXAMINE_OBJECT, 10355, -1, null));
		assertTrue("an object's examine forgets the item",
			reader.read(ChatMessageType.ITEM_EXAMINE, WHIP_LINE).isEmpty());
	}
}

package com.clanhub;

import java.awt.Color;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

/** {@link GearGlyph}, in memory: its size, its transparent corners and hole, and the colour of its ring. */
public class GearGlyphTest
{
	private static final Color ORANGE = new Color(220, 138, 0);

	private static BufferedImage image(ImageIcon icon)
	{
		return (BufferedImage) icon.getImage();
	}

	@Test
	public void theIconIsAsBigAsAskedAndNoSmallerThanTheMinimum()
	{
		final ImageIcon twelve = GearGlyph.icon(12, ORANGE);
		assertEquals(12, twelve.getIconWidth());
		assertEquals(12, twelve.getIconHeight());
		assertEquals(GearGlyph.MIN_SIZE, GearGlyph.icon(3, ORANGE).getIconWidth());
	}

	@Test
	public void theFourCornersAndTheHoleAreTransparent()
	{
		final BufferedImage img = image(GearGlyph.icon(12, ORANGE));
		assertEquals(0, img.getRGB(0, 0) >>> 24);
		assertEquals(0, img.getRGB(11, 0) >>> 24);
		assertEquals(0, img.getRGB(0, 11) >>> 24);
		assertEquals(0, img.getRGB(11, 11) >>> 24);
		assertEquals(0, img.getRGB(5, 5) >>> 24);
		assertEquals(0, img.getRGB(6, 6) >>> 24);
	}

	@Test
	public void theRingIsSolidInTheGivenColour()
	{
		// (8, 7) sits on the ring between two teeth: well inside the metal, so fully opaque.
		assertEquals(0xFF000000 | ORANGE.getRGB(), image(GearGlyph.icon(12, ORANGE)).getRGB(8, 7));
	}

	@Test
	public void noColourMeansTheSidebarsGrey()
	{
		assertEquals(0xFF000000 | ColorScheme.LIGHT_GRAY_COLOR.getRGB(), image(GearGlyph.icon(12, null)).getRGB(8, 7));
		assertEquals(new Color(165, 165, 165), ColorScheme.LIGHT_GRAY_COLOR);
	}
}

