/** {@link ItemCards}: a known item name becomes a card with its id and values, an unknown or only-similar name nothing. */
public class ItemCardsTest
{
	private static final String LINE = "Klar received a drop: Dragon claws (121,453,000 coins).";

	/** A search result the way the item manager gives one. */
	private static ItemPrice result(int id, String name)
	{
		final ItemPrice price = new ItemPrice();
		price.setId(id);
		price.setName(name);
		return price;
	}

	@Test
	public void aKnownNameBecomesACardAndAnUnknownNameNothing()
	{
		final ItemManager itemManager = Mockito.mock(ItemManager.class);
		when(itemManager.search("Dragon claws")).thenReturn(Collections.singletonList(result(13652, "Dragon claws")));
		when(itemManager.getItemPrice(13652)).thenReturn(121_453_000L);
		final ItemComposition composition = Mockito.mock(ItemComposition.class);
		when(composition.getHaPrice()).thenReturn(123_000);
		when(itemManager.getItemComposition(13652)).thenReturn(composition);
		final ItemCards cards = new ItemCards(itemManager);

		final HoverCard card = cards.forName("Dragon claws", 1, LINE, 24, 36);
		assertTrue("an item card", card instanceof ItemCard);
		final ItemCard item = (ItemCard) card;
		assertEquals(13652, item.id);
		assertEquals(121_453_000L, item.price);
		assertEquals(123_000, item.alch);
		assertEquals(1, item.quantity);
		assertEquals("Dragon claws", item.title());
		assertEquals(LINE, item.plainLine());
		assertEquals(24, item.start());
		assertEquals(36, item.end());

		assertNull("a name the item manager does not know", cards.forName("Nonsense", 1, LINE, 24, 36));

		final ItemManager similar = Mockito.mock(ItemManager.class);
		when(similar.search("Dragon claws")).thenReturn(Collections.singletonList(result(23_000, "Dragon claws (or)")));
		assertNull("only exact names count", new ItemCards(similar).forName("Dragon claws", 1, LINE, 24, 36));
	}

	@Test
	public void anUntradeableNameComesFromTheIndex()
	{
		final ItemManager itemManager = Mockito.mock(ItemManager.class);
		when(itemManager.search("Pet snakeling")).thenReturn(Collections.<ItemPrice>emptyList());
		when(itemManager.getItemPrice(12921)).thenReturn(0L);
		final ItemComposition composition = Mockito.mock(ItemComposition.class);
		when(composition.getHaPrice()).thenReturn(0);
		when(itemManager.getItemComposition(12921)).thenReturn(composition);
		final ItemNameIndex index = new ItemNameIndex();
		index.add(12921, "Pet snakeling");
		final String line = "Klar received a drop: Pet snakeling (0 coins).";

		final ItemCards cards = new ItemCards(itemManager, new DropRates(), index);
		final HoverCard card = cards.forName("Pet snakeling", 1, line, 0, 13);
		assertTrue("an item card", card instanceof ItemCard);
		final ItemCard item = (ItemCard) card;
		assertEquals(12921, item.id);
		assertEquals(0L, item.price);
		assertEquals("Pet snakeling", item.title());

		assertEquals(12921, cards.idOf("Pet Snakeling"));
		assertEquals(-1, cards.idOf("Nonsense"));
		assertEquals("with no index there is nothing to ask", -1, new ItemCards(itemManager).idOf("Pet snakeling"));
	}

	@Test
	public void theDropRatesFeedTheCard() throws Exception
	{
		final ItemManager itemManager = Mockito.mock(ItemManager.class);
		when(itemManager.search("Abyssal whip")).thenReturn(Collections.singletonList(result(4151, "Abyssal whip")));
		when(itemManager.getItemPrice(4151)).thenReturn(1_500_000L);
		final ItemComposition composition = Mockito.mock(ItemComposition.class);
		when(composition.getHaPrice()).thenReturn(72_000);
		when(itemManager.getItemComposition(4151)).thenReturn(composition);
		final String line = "Klar received a drop: Abyssal whip (1,500,000 coins).";
		final DropRates rates;
		try (Reader in = new InputStreamReader(ItemCardsTest.class.getResourceAsStream("/com/clanhub/drops-fixture.json"),
			StandardCharsets.UTF_8))
		{
			rates = DropRates.parse(in, new Gson());
		}

		final List<List<HoverCard.Pair>> rows = new ItemCards(itemManager, rates)
			.forName("Abyssal whip", 1, line, 0, 12).rows();
		// Re-aimed by the lead, 2026-10-08 (lot 8k): the table's order stands, four rows, then "and N more".
		assertEquals("the price row and two drop rows", 3, rows.size());
		// Re-aimed by the lead, 2026-10-08 (lot 8c): a drop row is the source and its rate, so a painter can right-align the rate.
		assertEquals("Abyssal demon", rows.get(1).get(0).label);
		assertEquals("1/512", rows.get(1).get(0).value);
		assertEquals("Greater abyssal demon", rows.get(2).get(0).label);
		assertEquals("1/256", rows.get(2).get(0).value);

		final List<List<HoverCard.Pair>> bare = new ItemCards(itemManager, new DropRates())
			.forName("Abyssal whip", 1, line, 0, 12).rows();
		assertEquals("a table that has not loaded adds no row", 1, bare.size());
	}

	@Test
	public void theRateOfANameIsItsFirstSources() throws Exception
	{
		final DropRates rates;
		try (Reader in = new InputStreamReader(ItemCardsTest.class.getResourceAsStream("/com/clanhub/drops-fixture.json"),
			StandardCharsets.UTF_8))
		{
			rates = DropRates.parse(in, new Gson());
		}
		final ItemCards cards = new ItemCards(Mockito.mock(ItemManager.class), rates);

		assertEquals("1/512", cards.rateOf("Abyssal whip"));
		assertEquals("the case rule is the lookup's", "1/512", cards.rateOf("abyssal WHIP"));
		assertEquals("1/4000", cards.rateOf("Pet Snakeling"));
		assertEquals("", cards.rateOf("Nothing at all"));
		assertEquals("no table", "", new ItemCards(Mockito.mock(ItemManager.class), null).rateOf("Abyssal whip"));
		assertEquals("a table that has not loaded", "",
			new ItemCards(Mockito.mock(ItemManager.class), new DropRates()).rateOf("Abyssal whip"));
	}

	/**
	 * A source whose name holds one of these is a container, which the table lists after every monster. A copy of
	 * CONTAINER_WORDS in docs/data/fetch_drops.py, which makes the order: keep the two the same.
	 */
	private static final String[] CONTAINER_WORDS = {"chest", "cache", "lockbox", "casket", "sack", "coffin", "impling",
		"reward", "crate", "supply", "jar", "pouch", "barrel", "urn", "nest", "unsired"};

	private static final String BUNDLED = "/com/clanhub/drops.json";

	private static boolean isContainer(String source)
	{
		final String name = source.toLowerCase(Locale.ROOT);
		for (final String word : CONTAINER_WORDS)
		{
			if (name.contains(word))
			{
				return true;
			}
		}
		return false;
	}

	private static Reader bundled()
	{
		return new InputStreamReader(ItemCardsTest.class.getResourceAsStream(BUNDLED), StandardCharsets.UTF_8);
	}

	@Test
	public void theBundledTableIsMonstersFirstAndSixAtMost() throws Exception
	{
		Assume.assumeNotNull(ItemCardsTest.class.getResource(BUNDLED));
		final JsonObject items;
		try (Reader in = bundled())
		{
			items = new Gson().fromJson(in, JsonObject.class).getAsJsonObject("items");
		}
		assertTrue("the table holds items", items.size() > 1000);
		for (final Map.Entry<String, JsonElement> item : items.entrySet())
		{
			final JsonArray sources = item.getValue().getAsJsonArray();
			assertTrue(item.getKey() + " has " + sources.size() + " sources, more than six", sources.size() <= 6);
			boolean containerSeen = false;
			for (final JsonElement source : sources)
			{
				final String from = source.getAsJsonObject().get("from").getAsString();
				if (isContainer(from))
				{
					containerSeen = true;
				}
				else
				{
					assertFalse(item.getKey() + " lists the monster " + from + " after a container", containerSeen);
				}
			}
		}

		final DropRates rates;
		try (Reader in = bundled())
		{
			rates = DropRates.parse(in, new Gson());
		}
		final List<DropRates.DropSource> whip = rates.lookup("Abyssal whip");
		assertEquals(3, whip.size());
		assertEquals("Greater abyssal demon", whip.get(0).from);
		assertEquals("Abyssal demon", whip.get(1).from);
		assertEquals("Unsired", whip.get(2).from);

		final List<DropRates.DropSource> platelegs = rates.lookup("Dragon platelegs");
		assertTrue("Dragon platelegs has at least five sources: " + platelegs.size(), platelegs.size() >= 5);
		assertFalse("and its first is a monster: " + platelegs.get(0).from, isContainer(platelegs.get(0).from));
	}
}

package com.clanhub;

import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

/** {@link ItemNameIndex}: built in slices, it keeps every real item's name, tradeable or not, and skips notes, placeholders and junk. */
public class ItemNameIndexTest
{
	/** An item the way the cache gives one: not a note, not a placeholder, the given name and worth. */
	private static ItemComposition item(String name, boolean tradeable, int alch, int note)
	{
		final ItemComposition composition = Mockito.mock(ItemComposition.class);
		when(composition.getName()).thenReturn(name);
		when(composition.isTradeable()).thenReturn(tradeable);
		when(composition.getHaPrice()).thenReturn(alch);
		when(composition.getNote()).thenReturn(note);
		when(composition.getPlaceholderTemplateId()).thenReturn(-1);
		return composition;
	}

	@Test
	public void buildsInChunksSkippingNotesPlaceholdersAndJunk()
	{
		final Client client = Mockito.mock(Client.class);
		when(client.getItemCount()).thenReturn(6);
		final ItemManager items = Mockito.mock(ItemManager.class);
		final ItemComposition[] compositions = {
			item("Dragon claws", true, 0, -1),
			item("Dragon claws", true, 0, 0),
			item("null", false, 0, -1),
			item("Man", false, 0, -1),
			item("Abyssal whip", true, 0, -1),
			item("Bones", false, 1, -1)};
		for (int id = 0; id < compositions.length; id++)
		{
			when(items.getItemComposition(id)).thenReturn(compositions[id]);
		}
		final ItemNameIndex index = new ItemNameIndex();
		assertFalse("not complete before it reads anything", index.complete());

		index.buildSome(client, items, 4);
		assertFalse(index.complete());
		assertEquals(4, index.next);
		assertEquals(Integer.valueOf(0), index.idOf("dragon claws"));
		assertNull(index.idOf("abyssal whip"));

		index.buildSome(client, items, 4);
		assertTrue(index.complete());
		assertEquals(Integer.valueOf(4), index.idOf("abyssal whip"));
		assertEquals(Integer.valueOf(5), index.idOf("bones"));
		assertNull(index.idOf("man"));
		assertNull(index.idOf("null"));
		assertEquals(3, index.size());
	}

	@Test
	public void keepsUntradeableNamesOfFiveCharactersOrMore()
	{
		final Client client = Mockito.mock(Client.class);
		when(client.getItemCount()).thenReturn(3);
		final ItemManager items = Mockito.mock(ItemManager.class);
		final ItemComposition[] compositions = {
			item("Pet snakeling", false, 0, -1),
			item("Man", false, 0, -1),
			item("null", false, 0, -1)};
		for (int id = 0; id < compositions.length; id++)
		{
			when(items.getItemComposition(id)).thenReturn(compositions[id]);
		}
		final ItemNameIndex index = new ItemNameIndex();

		index.buildSome(client, items, 10);

		assertTrue(index.complete());
		assertEquals(Integer.valueOf(0), index.idOf("pet snakeling"));
		assertNull(index.idOf("man"));
		assertNull(index.idOf("null"));
		assertEquals(1, index.size());
	}
}

package com.clanhub;

import com.clanhub.ClanHubConfig.CardTheme;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** {@link NatureScenes}: the six nature scenes, each looked at in the pixels of {@link SceneSky#of} at 420 by 190. */
public class NatureScenesTest
{
	private static final int W = 420;
	private static final int H = 190;

	private static BufferedImage sky(CardTheme theme)
	{
		return SceneSky.of(theme, W, H);
	}

	private static int red(BufferedImage image, int x, int y)
	{
		return (image.getRGB(x, y) >> 16) & 0xFF;
	}

	private static int green(BufferedImage image, int x, int y)
	{
		return (image.getRGB(x, y) >> 8) & 0xFF;
	}

	private static int blue(BufferedImage image, int x, int y)
	{
		return image.getRGB(x, y) & 0xFF;
	}

	private static int sum(BufferedImage image, int x, int y)
	{
		return red(image, x, y) + green(image, x, y) + blue(image, x, y);
	}

	/** The mean of red, green and blue added up over the columns {@code x0} up to {@code x1} and the rows {@code y0} up to {@code y1}. */
	private static double meanSum(BufferedImage image, int x0, int x1, int y0, int y1)
	{
		long total = 0;
		for (int y = y0; y < y1; y++)
		{
			for (int x = x0; x < x1; x++)
			{
				total += sum(image, x, y);
			}
		}
		return total / (double) ((x1 - x0) * (y1 - y0));
	}

	/**
	 * Lot 10U: Forest has leaves in the top right, fireflies over most of the card and dark pines at the bottom left.
	 */
	@Test
	public void forest()
	{
		final BufferedImage sky = sky(CardTheme.FOREST);
		boolean leaf = false;
		for (int y = 0; y < 14; y++)
		{
			for (int x = W * 2 / 3; x < W; x++)
			{
				leaf |= green(sky, x, y) - red(sky, x, y) > 40 && green(sky, x, y) > 90;
			}
		}
		assertTrue("a leaf-green pixel in the top 14 px of the right third", leaf);

		boolean firefly = false;
		for (int y = 0; y < H; y++)
		{
			for (int x = (int) (W * 0.3); x < W; x++)
			{
				firefly |= red(sky, x, y) > 200 && green(sky, x, y) > 200 && blue(sky, x, y) < 170;
			}
		}
		assertTrue("a firefly pixel in the right 70 %", firefly);

		assertTrue("the bottom left is dark", meanSum(sky, 0, 60, H - 16, H) < 120);
	}

	/** Lot 10U: Ocean has a bubble at the right, kelp at the bottom right, and is lighter at the top than the bottom. */
	@Test
	public void ocean()
	{
		final BufferedImage sky = sky(CardTheme.OCEAN);
		boolean bubble = false;
		for (int y = 0; y < H; y++)
		{
			for (int x = W - 90; x < W; x++)
			{
				bubble |= red(sky, x, y) > 200 && green(sky, x, y) > 200 && blue(sky, x, y) > 200;
			}
		}
		assertTrue("a bubble pixel in the right 90 px", bubble);

		boolean kelp = false;
		for (int y = H - 60; y < H; y++)
		{
			for (int x = (int) (W * 0.3); x < W; x++)
			{
				kelp |= green(sky, x, y) - red(sky, x, y) > 40 && green(sky, x, y) > blue(sky, x, y);
			}
		}
		assertTrue("a kelp pixel in the bottom 60 px of the right 70 %", kelp);

		assertTrue("the top is brighter than the bottom", meanSum(sky, 0, W, 0, 20) > meanSum(sky, 0, W, H - 20, H));
	}

	/** Lot 10U: Autumn has a leaf at the bottom and the low sun at the right. */
	@Test
	public void autumn()
	{
		final BufferedImage sky = sky(CardTheme.AUTUMN);
		boolean leaf = false;
		for (int y = H - 8; y < H; y++)
		{
			for (int x = 0; x < W; x++)
			{
				leaf |= red(sky, x, y) > 180 && green(sky, x, y) < 170 && blue(sky, x, y) < 80;
			}
		}
		assertTrue("a maple-leaf pixel in the bottom 8 px", leaf);

		final int y = (int) (H * 0.55);
		assertTrue("the sun is at the right", sum(sky, W - 50, y) > sum(sky, 60, y));
	}

	/** Lot 10U: Sakura has blossom at the top right and a pale moon. */
	@Test
	public void sakura()
	{
		final BufferedImage sky = sky(CardTheme.SAKURA);
		boolean blossom = false;
		for (int y = 0; y < 34; y++)
		{
			for (int x = W - 170; x < W; x++)
			{
				blossom |= red(sky, x, y) > 230 && green(sky, x, y) >= 150 && green(sky, x, y) <= 215
					&& blue(sky, x, y) > 190;
			}
		}
		assertTrue("a blossom pixel in the top 34 px of the right 170 px", blossom);

		boolean moon = false;
		for (int y = 30 - 12; y <= 30 + 12; y++)
		{
			for (int x = W - 64 - 12; x <= W - 64 + 12; x++)
			{
				moon |= (x - (W - 64)) * (x - (W - 64)) + (y - 30) * (y - 30) <= 144 && sum(sky, x, y) > 650;
			}
		}
		assertTrue("a moon pixel near the top right", moon);
	}

	/** Lot 10U: Garden has a fence, tulips at the bottom and a rose at the right. */
	@Test
	public void garden()
	{
		final BufferedImage sky = sky(CardTheme.GARDEN);
		boolean fence = false;
		for (int y = H - 34; y < H; y++)
		{
			for (int x = 0; x < W; x++)
			{
				fence |= red(sky, x, y) > 200 && green(sky, x, y) > 200 && blue(sky, x, y) > 200;
			}
		}
		assertTrue("a fence pixel in the bottom 34 px", fence);

		boolean tulip = false;
		for (int y = H - 22; y < H; y++)
		{
			for (int x = 0; x < W; x++)
			{
				tulip |= red(sky, x, y) > 200 && green(sky, x, y) < 90;
			}
		}
		assertTrue("a tulip pixel in the bottom 22 px", tulip);

		boolean rose = false;
		for (int y = 0; y < H; y++)
		{
			for (int x = W - 16; x < W; x++)
			{
				rose |= red(sky, x, y) > 180 && green(sky, x, y) < 60 && blue(sky, x, y) < 90;
			}
		}
		assertTrue("a rose pixel in the right 16 px", rose);
	}

	/** Lot 10U: each of the six is painted at any size, down to a single pixel, with its edge colour in the corner. */
	@Test
	public void everySizeIsPainted()
	{
		final CardTheme[] themes = {CardTheme.FOREST, CardTheme.OCEAN, CardTheme.AUTUMN, CardTheme.SAKURA,
			CardTheme.GARDEN, CardTheme.LAVENDER};
		final int[][] sizes = {{1, 1}, {10, 10}, {30, 30}, {200, 40}, {100, 300}, {900, 600}};
		for (final CardTheme theme : themes)
		{
			for (final int[] size : sizes)
			{
				final BufferedImage image = SceneSky.of(theme, size[0], size[1]);
				assertEquals(theme + " width", size[0], image.getWidth());
				assertEquals(theme + " height", size[1], image.getHeight());
				assertEquals(theme + " edge in the corner at " + size[0] + " by " + size[1], SceneSky.edge(theme).getRGB(),
					image.getRGB(0, 0));
			}
		}
	}

	/** Lot 10U: Lavender has a field at the bottom with poppies in it, and a sky that lightens toward the horizon. */
	@Test
	public void lavender()
	{
		final BufferedImage sky = sky(CardTheme.LAVENDER);
		boolean lavender = false;
		for (int y = (int) (H * 0.85); y < H; y++)
		{
			for (int x = 0; x < W; x++)
			{
				lavender |= blue(sky, x, y) > 200 && red(sky, x, y) > 140 && green(sky, x, y) < 175;
			}
		}
		assertTrue("a lavender pixel in the bottom 15 %", lavender);

		boolean poppy = false;
		for (int y = (int) (H * 0.8); y < H; y++)
		{
			for (int x = 0; x < W; x++)
			{
				poppy |= red(sky, x, y) > 200 && green(sky, x, y) < 70 && blue(sky, x, y) < 70;
			}
		}
		assertTrue("a poppy pixel in the bottom 20 %", poppy);

		assertTrue("dusk: the sky lightens toward the horizon", sum(sky, W / 2, 4) < sum(sky, W / 2, (int) (H * 0.75)));
	}
}

package com.clanhub;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** {@link NavIcon}, in memory: the size, the coin exactly as {@link CoinGlyph} draws it, the picture clear of it. */
public class NavIconTest
{
	/** The coin's centre and the farthest its jittered rim reaches from it, with a pixel of margin. */
	private static final double COIN_CENTRE = 4.5;
	private static final double CLEAR_DISTANCE = 6.0;

	private static BufferedImage coinAlone()
	{
		final BufferedImage img = new BufferedImage(NavIcon.SIZE, NavIcon.SIZE, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			CoinGlyph.paint(g);
		}
		finally
		{
			g.dispose();
		}
		return img;
	}

	@Test
	public void theIconIsSixteenBySixteenArgb()
	{
		final BufferedImage icon = NavIcon.create();
		assertEquals(16, icon.getWidth());
		assertEquals(16, icon.getHeight());
		assertEquals(BufferedImage.TYPE_INT_ARGB, icon.getType());
	}

	@Test
	public void theCoinIsDrawnPixelForPixelAsTheCoinGlyphDrawsIt()
	{
		final BufferedImage icon = NavIcon.create();
		final BufferedImage coin = coinAlone();
		int coinPixels = 0;
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				if ((coin.getRGB(x, y) >>> 24) != 0)
				{
					coinPixels++;
					assertEquals("coin pixel " + x + "," + y, coin.getRGB(x, y), icon.getRGB(x, y));
				}
			}
		}
		assertTrue("the coin drew something", coinPixels > 0);
	}

	@Test
	public void thePictureLiesClearOfTheCoinsCircle()
	{
		final BufferedImage icon = NavIcon.create();
		final BufferedImage coin = coinAlone();
		int pictureOnly = 0;
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				if (icon.getRGB(x, y) != coin.getRGB(x, y))
				{
					pictureOnly++;
					final double dx = x + 0.5 - COIN_CENTRE;
					final double dy = y + 0.5 - COIN_CENTRE;
					assertTrue("picture pixel " + x + "," + y + " is too near the coin",
						Math.sqrt(dx * dx + dy * dy) >= CLEAR_DISTANCE);
				}
			}
		}
		assertTrue("the picture drew something", pictureOnly > 0);
	}

	private static final int PARCHMENT = 0xFFCDBE9E;
	private static final int CLAN = 0xFF0000B0;
	private static final int HOVER = 0xFF3B82F6;
	private static final int WHITE = 0xFFF0F0F0;
	private static final int INK = 0xFF16161A;

	private static void assertPixel(String what, int expected, BufferedImage icon, int x, int y)
	{
		assertEquals(what + " at " + x + "," + y, expected, icon.getRGB(x, y));
	}

	@Test
	public void thePictureIsTheHoveredChatLineAndTheCardAbove()
	{
		final BufferedImage icon = NavIcon.create();
		final BufferedImage coin = coinAlone();
		int differing = 0;
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				if (icon.getRGB(x, y) != coin.getRGB(x, y))
				{
					differing++;
				}
			}
		}
		assertEquals("the picture's pixels", 107, differing);

		for (int x = 0; x < NavIcon.SIZE; x++)
		{
			// Rows 0 and 9 hold only the coin's own rim (left of x 10): the picture adds nothing, the row of air.
			assertEquals("row 0 is the coin alone at " + x, coin.getRGB(x, 0), icon.getRGB(x, 0));
			assertEquals("row 9 is the coin alone at " + x, coin.getRGB(x, 9), icon.getRGB(x, 9));
			if (x >= 10)
			{
				assertEquals("row 0 transparent at " + x, 0, icon.getRGB(x, 0) >>> 24);
				assertEquals("row 9 transparent at " + x, 0, icon.getRGB(x, 9) >>> 24);
			}
			for (int y = 10; y <= 12; y++)
			{
				assertEquals("row " + y + " opaque at " + x, 255, icon.getRGB(x, y) >>> 24);
			}
		}

		// The strip's parchment at its two top corners, the clan's blue along the line, the lit word.
		assertPixel("parchment", PARCHMENT, icon, 0, 10);
		assertPixel("parchment", PARCHMENT, icon, 15, 10);
		assertPixel("clan blue", CLAN, icon, 1, 11);
		assertPixel("clan blue", CLAN, icon, 8, 11);
		assertPixel("hover blue", HOVER, icon, 9, 11);
		assertPixel("hover blue", HOVER, icon, 10, 11);
		// The title bar and its two cut corners, the window's cut bottom corner.
		assertPixel("hover blue", HOVER, icon, 12, 1);
		assertPixel("hover blue", HOVER, icon, 10, 2);
		assertEquals("title bar corner cut at 10,1", 0, icon.getRGB(10, 1) >>> 24);
		assertEquals("title bar corner cut at 15,1", 0, icon.getRGB(15, 1) >>> 24);
		assertEquals("window corner cut at 10,8", 0, icon.getRGB(10, 8) >>> 24);
		// The window's white and the ink of its two lines.
		assertPixel("white", WHITE, icon, 12, 3);
		assertPixel("white", WHITE, icon, 10, 5);
		assertPixel("ink", INK, icon, 11, 4);
		assertPixel("ink", INK, icon, 14, 4);
		assertPixel("ink", INK, icon, 13, 6);
		assertPixel("white", WHITE, icon, 14, 6);
